    'cli.doctor.sandbox_binary' => '{backend} unter {path}',
    'cli.doctor.sandbox_binary_absent' => '{backend} nicht im PATH gefunden',
    'cli.doctor.sandbox_nonlinux' => 'bashSandbox "{mode}" konfiguriert, aber bubblewrap ist nur für Linux und dieser Host ist {os}',
    'cli.doctor.sandbox_nonlinux_off' => 'bashSandbox deaktiviert; bubblewrap ist nur für Linux und dieser Host ist {os}',
