    'cli.doctor.sandbox_remedy_apparmor' => 'bubblewrap installieren oder ein /etc/apparmor.d-Profil hinzufügen, das bwrap unprivilegierte Benutzernamensräume gewährt (der apparmor_restrict_unprivileged_userns sysctl ist die grobe Rückfalllösung)',
    'cli.doctor.sandbox_remedy_generic' => 'bubblewrap installieren oder bashSandbox auf "off" setzen',
    'cli.doctor.sandbox_remedy_seatbelt' => 'prüfen, ob /usr/bin/sandbox-exec auf dieser macOS-Installation noch läuft, oder bashSandbox auf "off" setzen',
    'cli.doctor.server_ready' => 'pcntl, posix und ffi verfügbar — `serve` kann starten',
    'cli.doctor.server_refuses' => '`serve` wird den Start verweigern: {problems}',
    'cli.doctor.sessions' => '{count} Sitzung(en) gespeichert',
    'cli.doctor.settings_clean' => 'jede Einstellungsdatei enthält nur Schlüssel, die candy-code liest',
    'cli.doctor.unknown' => 'unbekannt',
    'cli.headless.permission_hint' => '  Hinweis: Ein `-p`-Lauf ohne benannten Modus startet im fragenden `default`-Modus; unbeaufsichtigte Anfragen haben niemanden zum Antworten, daher scheitern sie im geschlossenen Zustand. Skriptläufe können --permission-mode bypass-permissions (oder accept-edits) angeben, um fortzufahren.',
    'cli.help.screen' => <<<'TXT'
CandyCode — KI-Coding-Assistent für das Terminal.

Verwendung:
  candy-code                       Interaktive TUI starten (Standard)
  candy-code <dir>                 TUI mit Wurzel <dir> starten, das
                                   vorhanden sein muss (nur als erstes Argument)
  candy-code [<dir>] <words…>      TUI starten und die Wörter als
                                   ersten Prompt senden, z. B. candy-code fix the bug
  candy-code -c                    Letzte Sitzung fortsetzen
  candy-code --resume [<id>]       Gespeicherte Sitzung fortsetzen (Auswahl ohne id)
  candy-code -p <prompt>           Einzelnen Prompt ausführen und beenden (einmalig)
  candy-code run "<prompt>"        Alias für -p "<prompt>" (einmaliger Modus)
  candy-code --output-format json  Maschinenlesbares JSON ausgeben (einmalig)
  candy-code --worktree [<name>]   Sitzung in einem eigenen git-Worktree
                                   ausführen (wird erstellt, falls nicht vorhanden)

Unterbefehle (keiner öffnet die TUI oder benötigt einen Anbieter, einen API-Schlüssel oder ein
Terminal; jeder antwortet und beendet sich, außer serve und mcp serve, die laufen, bis
sie gestoppt werden — und attach, das die Ausnahme von beiden ist: Es führt die TUI auf einer laufenden Server-
Sitzung aus; acp führt Runden für einen Editor aus, bis der Editor sich trennt):
  bundles list           Plugin-Bundles auflisten, die dieses Verzeichnis sieht: Name,
                         Version, Ebene und die Flächen, die jedes trägt —
                         einschließlich der Hooks und .mcp.json, die candy-code
                         nicht ausführt.
  bundles install <src>  Bundle-Verzeichnis kopieren oder eine git-URL mit
                         begrenztem Tiefen-eins-Klon in das Benutzer-Bundle-Verzeichnis
                         (~/.candy-code/bundles) kopieren, wo nur du Eigentümer bist.
  doctor                 Diese Installation prüfen und jedes Problem melden, das
                         sie findet: PHP-Version, die Erweiterungen, die der Sitzungsspeicher
                         und serve benötigen, die Konfigurationsdatei, die Berechtigungs-
                         richtlinie, der ausgewählte Anbieter, die Sitzungsdatenbank
                         und die Projekt-MCP-Konfiguration. Exit 1, wenn eine Prüfung
                         FEHLTSCHLÄGT.
                         Unterscheidet sich vom modellaufrufbaren "doctor"-Tool, das
                         das Bildprotokoll des Terminals an das Modell meldet.
  import claude          Vorschau des Claude Code-Settings-Imports: liest Claudes Benutzer-
                         Einstellungsdatei, plus die .claude Einstellungsdatei unter dem Start-
                         verzeichnis bei Angabe von --project, übersetzt deren Berechtigungs-
                         allow/deny/ask-Listen in permissionRules (die strengere Seite
                         gewinnt immer — deny schlägt allow), bildet das Modell ab und benennt
                         jeden Schlüssel, für den kein Platz existiert, als skipped. Nichts wird
                         geschrieben, bis bestätigt: --yes akzeptiert die gedruckte Vorschau
                         direkt, und ohne sie wird ein interaktives Terminal gefragt. Die
                         Vorschau benennt jede allow-Regel, die erweitern würde, was ohne Rückfrage läuft.
  login <provider>       Einen Anbieter anmelden: claude-code und codex übergeben das
                         Terminal an ihre eigene CLI (das Token durchläuft
                         nie candy-code); openai, anthropic und gemini
                         fügen einen Schlüssel in den providers-Block der Konfigurationsdatei ein;
                         die übrigen benennen den tatsächlichen Inhaber des Zugangs.
  models                 Listet die Anbieter dieser Installation und das
                         Standardmodell jedes einzelnen; "*" markiert den
                         ausgewählten.
  session list [--all|--archived|--children] [--limit N]
                         Listet gespeicherte Sitzungen, angepinnte zuerst, dann neueste
                         zuerst: ID, letzte Aktualisierung, Typ, Runden, Anbieter/Modell
                         und Name (★ markiert eine angepinnte Zeile). --children fügt
                         Sub-Agent- und Hintergrundzeilen hinzu, --archived fügt
                         archivierte hinzu, --all fügt beide hinzu; 20 Zeilen, außer
                         --limit bestimmt anders.
  session show <target>  Druckt Details und Transkript einer Sitzung.
  session rename <target> <title…>
                         Benennt eine Sitzung um; die Wörter nach dem Ziel sind
                         der Titel.
  session delete <target> [--with-children]
                         Löscht eine Sitzung. Sub-Agent-Kinder werden mitgelöscht;
                         Zweige bleiben erhalten, außer --with-children.
  session pin|unpin|archive|unarchive <target>
                         Pinnt eine Sitzung (zuerst gelistet, nie bereinigt), oder
                         archiviert sie (aus der Standardliste ausgeblendet, behalten).
                         <target> ist eine ID, ein Name oder ein eindeutiges ID-Präfix.
                         Exit 1, wenn nichts passt, 2 wenn ein Präfix
                         mehrdeutig ist (die Kandidaten werden gelistet).
  mcp list               Listet die MCP-Server, die .mcp.json deklariert, OHNE
                         einen davon zu starten. Meldet stattdessen, wenn die Datei
                         fehlt, außerhalb des Projektbaums auflöst oder
                         vorhanden ist, aber das Projektverzeichnis nicht vertrauenswürdig ist.
  mcp trust              Genehmigt die .mcp.json dieses Projekts so wie sie ist: fügt
                         das Stammverzeichnis zu "trustedProjectMcp" hinzu und protokolliert
                         Befehl, args und env jedes Servers, damit eine spätere Änderung
                         an einem davon beim Start verweigert wird, bis erneut genehmigt.
                         Startet nichts.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Übersetzt eine fremde MCP-Konfiguration und druckt den
                         äquivalenten .mcp.json-Block nach stdout. Druckt nur
                         standardmäßig; --write user fügt die übersetzten
                         Einträge in die ~/.candy-code/mcp.json des Benutzers hinzu
                         (ein Namenskonflikt verweigert den gesamten Schreibvorgang, und die
                         Projekt-Ebene wird nie geschrieben). Die Umbenennungen, die
                         die Übersetzung vornahm, werden auf stderr gelistet.
  mcp serve [--root PATH]
                         Dient candy-code selbst als MCP-Server über stdio:
                         ein JSON-RPC-Frame pro Zeile rein, eine Antwort pro Zeile
                         raus, bis stdin schließt. Tool-Aufrufe führen die schreibgeschützte
                         Liste aus (Read, Glob, Grep, Ls, RepoMap), eingesperrt in das
                         Arbeitsverzeichnis, durch die PermissionGate des Starts
                         und die PreToolUse-Hook-Kette — dies ist der MCP-
                         Server, den ein Client starten kann; der WebSocket-
                         `candy-code serve` spricht weiterhin kein MCP. Läuft bis
                         gestoppt.
  lsp install <language> Installiert den angepinnten Language Server für eine
                         Sprache: das npm-Paket oder die prüfsummenverifizierte
                         Release-Binary, in das private Installationsverzeichnis unter
                         dem Home-Verzeichnis. `lsp list` zeigt, welche Sprachen
                         installierbar sind.
  lsp list               Meldet jede installierbare Sprache: ihre angepinnte
                         Version, wo ihr Server installiert ist (oder dass er
                         es nicht ist), und ob ein Release für das OS und die
                         Architektur dieses Rechners existiert. Startet nichts,
                         lädt nichts herunter.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Ersetzt diese phar-Installation durch die neueste veröffentlichte
                         candy-code-Version, sha256-verifiziert gegen die
                         Release-Sidecar VOR dem Austausch; die laufende phar wird
                         als <phar>.old behalten und --rollback stellt genau
                         diese Kopie einmal wieder her. Wenn ein Signaturschlüssel
                         in der Release-Quelle angepinnt ist, muss die candy-code.phar.minisig-
                         Signatur ebenfalls verifiziert werden (--allow-unsigned überspringt
                         nur diesen Teil). --check meldet nur aktuell vs.
                         neueste und exitet 1, wenn ein Update verfügbar ist. Eine
                         Composer-Installation wird laut verweigert, mit Nennung des
                         composer-update-Befehls, der stattdessen auszuführen ist. Eine
                         dev-gebaute Installation folgt dem rollenden candy-code/dev-Release
                         standardmäßig (sie ist aktuell, wenn der Ziel-Commit des Releases
                         dem sha des Stamps entspricht) und --channel
                         wählt explizit eine der beiden Linien.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         WebSocket- und HTTP-Server für die Web-UI starten,
                         im Vordergrund bis Strg+C. Bindet standardmäßig
                         127.0.0.1:7420 und gibt eine Anmelde-URL aus, deren
                         Einmal-Code gegen ein Browser-Cookie getauscht wird;
                         jeder Client braucht ihn oder das Token in
                         ~/.candy-code/server/token, Loopback eingeschlossen.
                         Optionen:
      --host <ip>        Adresse zum Binden (Standard 127.0.0.1; localhost und
                         ::1 zählen ebenfalls als Loopback). Jede andere
                         Adresse wird abgelehnt, außer --allow-remote ist
                         ebenfalls gesetzt.
      --port <n>         Port zum Binden (Standard 7420; 0 wählt einen freien).
      --allow-remote     Nicht-Loopback-Host erlauben. Ohne --tls-cert und
                         --tls-key läuft es als Klartext-HTTP: einen
                         TLS-Reverse-Proxy davor schalten oder direkt TLS
                         bedienen (siehe unten). Bei 0.0.0.0 oder :: antwortet
                         der Server auf den eigenen Adressen des Rechners, und
                         die Anmelde-URL nennt diese.
      --tls-cert <file>  PEM-Zertifikat, mit dem der Listener selbst TLS
                         bedient, zusammen mit --tls-key angegeben. Die
                         Anmelde-URL lautet dann https://, das Session-Cookie
                         trägt Secure, und ein http://-Client erhält keine
                         Antwort.
      --tls-key <file>   PEM-Privatschlüssel für --tls-cert: eine lesbare Datei
                         ohne Gruppen- oder Weltrechte, passend zum
                         Zertifikat. Ein fehlerhaftes oder unvollständiges
                         Paar wird beim Start abgelehnt.
      --allowed-host <list>
                         Kommagetrennte zusätzliche Hostnamen (oder
                         Host:Port), auf denen der Server antwortet, z. B. ein
                         DNS-Name für diesen Rechner. Wiederholbar.
      --allowed-ips <list>
                         Kommagetrennte Client-IPs oder CIDR-Bereiche (z. B.
                         1.2.3.4,10.0.0.0/8), die sich verbinden dürfen; jede
                         andere Adresse wird vor der Anmeldung mit 403
                         abgelehnt. Loopback ist immer erlaubt. Nicht gesetzt:
                         keine Adressfilterung. Wiederholbar.
      --allowed-origin <list>
                         Kommagetrennte zusätzliche Browser-Origin
                         (http(s)://host[:port]) neben dem eigenen des
                         Servers. Wiederholbar.
      --allow-dir-browse Angemeldeten Clients erlauben, das Verzeichnis für
                         eine neue Sitzung auszuwählen: Sie dürfen
                         Verzeichnisnamen (nie Dateien) unter --browse-root
                         auflisten. Standardmäßig aus.
      --browse-root <dir>
                         Verzeichnis, auf das --allow-dir-browse beschränkt ist
                         (Standard: Ihr Home-Verzeichnis).
      --web-root <dir>   Web-UI aus <dir> ausliefern statt aus dem
                         installierten Paket sugarcraft/candy-code-web.
      --no-web           Nur API und WebSocket bedienen, keine UI-Dateien.
      --allow-bypass     Sitzungen in bypass-permissions oder dont-ask
                         erlauben (standardmäßig abgelehnt; die Sitzungen des
                         Servers starten im Standardmodus, außer
                         --permission-mode sagt etwas anderes).
      --allow-root       Ausführung als root erlauben (standardmäßig
                         abgelehnt).
      --detach           Im Hintergrund laufen: URL und PID ausgeben, sobald
                         der Port gebunden ist, dann beenden; der Server
                         protokolliert in server.log im Zustandsverzeichnis.
      --parent-pid <pid> Server stoppen, wenn Prozess <pid> endet (für einen
                         Editor oder eine TUI, die einen privaten Server
                         startet). Startet nicht ohne ext-pcntl, ext-posix und
                         ext-ffi (siehe doctor). Exit-Code 1, wenn der Port
                         belegt ist oder bereits ein Server aus demselben
                         Zustandsverzeichnis läuft.
  serve status           Laufenden Server melden: PID, URL, Root, Laufzeit und
                         ob GET /api/health antwortet. Exit-Code 1, wenn
                         keiner läuft.
  serve stop [--force]   Server stoppen: SIGTERM, bis zu 30 s zum Abwarten,
                         dann SIGKILL.
      --force            Sofort SIGKILL.
  serve logs [-f]        Ende des Protokolls eines freigestellten Servers
                         ausgeben.
  -f, --follow           Fortlaufend ausgeben, was angehängt wird, bis der
                         Server stoppt.
  serve url [--qr]       Anmelde-URL mit frischem Einmal-Code ausgeben.
      --qr              Jede Anmelde-URL als scannbaren Terminal-QR-Code
                         darstellen.
  serve token [--rotate] Owner-Token ausgeben, das Bearer-Clients senden.
      --rotate           Ersetzen; ein laufender Server behält das alte bis
                         zum Neustart.
  attach [<session>] [--url <url>]
                         TUI auf einer Sitzung eines laufenden candy-code
                         serve ausführen: Der Server führt jede Runde und ihre
                         das Projektstammverzeichnis des Editors, hier laufen die Runden mit diesem
                         Anbieter und Tools der Installation, und die Antworten des Editors
                         ihre Berechtigungsfragen. Nicht für ein Terminal: stdout
                         überträgt nur das Protokoll (alles andere geht an
                         stderr). Beendet mit 0, wenn der Editor stdin schließt.
  completion bash|zsh|fish
                         Shell-Completion-Skript nach stdout schreiben, z. B.
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Dauerhaftes Ausgabenverzeichnis nach Tag und Modell aggregieren:
                         dieselbe Seite, die `/usage` ausgibt, über dieselbe gemeinsame
                         einklappen. 7 und 30 nehmen ganze UTC-Tage einschließlich heute,
                         alle (oder kein Operand) umfassen das gesamte Register, und ein
                         Fenster außerhalb dieses Sets wird abgelehnt statt
                         stillschweigend erweitert. --session schränkt auf eine Sitzung ein
                         nach ID, Name oder eindeutigem Präfix; --output-format json
                         gibt die Fakten-Map aus, aus der die Seite erstellt wurde. Ein
                         unlesbares Ledger nennt seinen Grund und beendet sich mit 1;
                         Dollar für Folds, die ein nicht bepreistes Modell enthalten
                         als ≥ Untergrenze ausgeben, niemals als einfache Summe.

Optionen:
  -p, --prompt <text>    Prompt in der Befehlszeile angeben (Einmalmodus)
      --output-format <format>
                         Ausgabeformat: "text" (Standard), "json" oder
                         "stream-json" (NDJSON-Ereignisse, Antwort am Ende)
      --root <dir>       <dir> als Projektstamm statt des aktuellen verwenden
                         Verzeichnis. Akzeptiert auch --root=<dir> (die zu verwendende Form
                         wenn <dir> mit "-") beginnt; es darf nicht weggelassen werden.
                         Einen root hier UND als positionsargument zu benennen ist
                         abgelehnt, anstatt dass eines still gewinnt.
      --config <file>    Einstellungen, Berechtigungen und vertrauenswürdige Hook-Wurzeln lesen aus
                         <file> anstelle von ~/.candy-code/config.json. Außerdem
                         akzeptiert --config=<file>. Muss bereits vorhanden sein, 
                         lesbar, Ihnen gehören und weder es noch sein
                         Verzeichnis ist möglicherweise world-writable — es enthält die
                         Berechtigungsrichtlinie, sodass es demselben Maßstab unterliegt
                         als ~/.candy-code/config.json (eine Datei unter /etc oder
                         /tmp wird normalerweise aus einem dieser Gründe abgelehnt).
                         Nur die DATEI wird verschoben: Agents, Skills, Workflows,
                         Sitzungen und Speicher bleiben in ~/.candy-code.
      --model <name>     <name> als Konversationsmodell verwenden, überschreibt
                         $CANDY_CODE_MODEL und dem eigenen Standard des Anbieters. Außerdem
                         akzeptiert --model=<name>. Wählt ein Modell aus, keinen Anbieter
                         — der Anbieter kommt weiterhin aus $CANDY_CODE_PROVIDER oder
                         der gespeicherten `provider`-Einstellung, und beide sind
                         unabhängige Achsen.
      --permission-mode <mode>
                         Unter <mode> laufen lassen statt des Modus in der Konfigurations-
                         datei. Akzeptiert auch --permission-mode=<mode>. Höchste
                         Priorität: überschreibt $CANDY_CODE_PERMISSION_MODE und
                         den Konfigurationsschlüssel permissionMode. Einer von: default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Ohne Angabe starten TUI und -p
                         im Modus default (fragt vor Schreibzugriffen und Shell-
                         befehlen); nur ein lokal gestarteter Daemon startet im
                         Modus bypass-permissions.
      --max-cost <usd>   Begrenzt diesen Start auf <usd> US-Dollar gemeldeten
                         Verbrauchs: der Turn, der die Obergrenze überschreiten würde,
                         wird abgelehnt und nicht gesendet. Akzeptiert auch --max-cost=<usd>.
                         Höchste Priorität: überschreibt $CANDY_CODE_MAX_COST und
                         den Konfigurationsschlüssel maxCostUsd. Dezimalwerte erlaubt, ein
                         führendes $ akzeptiert ($2.50); Null und negative Werte werden
                         abgelehnt statt als "kein Limit" gelesen. /budget kann weiterhin
                         das Limit der laufenden Sitzung erhöhen oder aufheben.
      --max-turns <n>    Begrenzt diesen Start auf <n> Tool-Loop-Schritte: der Turn,
                         der sie alle aufbraucht, stoppt an dieser Stelle und teilt es mit.
                         Akzeptiert auch --max-turns=<n>. Höchste Priorität:
                         überschreibt den Einstellungsschlüssel maxToolSteps (diese Achse
                         hat keine Umgebungsvariable). Eine positive ganze
                         Zahl; Null wird abgelehnt statt als "kein
                         Limit" gelesen, und ein unbrauchbarer Wert lehnt den Start ab,
                         statt stillschweigend auf die Einstellung zurückzufallen.
      --json-schema <path-or-json>
                         Schränkt die Antwort auf ein JSON Schema ein: ein Inline-
                         {"type":"object",...}-Dokument oder ein Pfad zu einer Datei
                         mit einem solchen. Akzeptiert auch --json-schema=<value>;
                         die =-Form ist zu verwenden, wenn der Pfad mit
                         "-" beginnt. Nur Anbieter, die schema-beschränkte
                         Antworten unterstützen, führen die Anfrage überhaupt aus
                         — alles andere wird mit Exit-Code 2 abgelehnt, statt
                         für eine unbeschränkte Antwort abzurechnen. Das Schema
                         steuert die selbstbeendende Anfrage des Turns; Schritte,
                         die einen Tool-Loop fortsetzen, bleiben frei (eine erzwungene
                         JSON-Antwort kann keine Tool-Aufrufe enthalten).
      --append-system-prompt <text-or-@file>
                         Fügt Operator-Regeln zum System-Prompt dieses
                         einzelnen Starts hinzu: Inline-Text oder @Pfad zu einer Datei mit
                         solchen. Akzeptiert auch --append-system-prompt=<value>;
                         die =-Form ist zu verwenden, wenn der Pfad mit
                         mit "-". Die Regeln werden als ein weiterer umrahmter
                         persönlicher Anweisungsblock übergeben, niemals als Überschreibung: Sie
                         können die darüberliegenden Ebenen weder ersetzen noch herabstufen, und
                         gefälschte Block-Marker im Text werden neutralisiert.
                         Begrenzt auf dieselbe Größe wie ein Anweisungsdokument.
                         Nur mit -p oder dem run-Verb: Ein Start ohne
                         Prompt zum Anhängen verweigert mit Exit-Code 2, statt
                         die übergebenen Regeln stillschweigend zu ignorieren.
  -c, --continue         Zuletzt verwendete Sitzung wieder öffnen, Transcript
                         und alles, statt eine neue zu starten. Ohne diese
                         Option öffnet jeder Start eine neue Sitzung; ↑ in einem leeren
                         Eingabefeld ruft weiterhin Prompts aus früheren Sitzungen auf.
      --resume [<id|name>]
                         Gespeicherte Sitzung per ID, eindeutiges ID-Präfix oder
                         Namen öffnen (siehe `session list`). Ohne Wert wird die
                         Sitzungsauswahl beim Start geöffnet; neben -p ist ein Ziel
                         ERFORDERLICH (das Transcript speist den One-Shot, und die
                         Antwort wird in den Datensatz zurückgeschrieben). Akzeptiert auch
                         --resume=<id>. Nicht kombinierbar mit --continue.
      --worktree [<name>]
                         Ganze Sitzung in einem Git-Worktree
                         main-<name> auf dem Branch candy-code/<name> ausführen, erstellt
                         bei erster Verwendung; ohne Namen erhält der Worktree einen
                         automatisch gewählten. Beim Beenden wird ein Worktree ohne
                         Commits und ohne Änderungen wieder entfernt; einer mit
                         Arbeit bleibt bestehen und gibt seinen Pfad aus. Verweigert
                         außerhalb eines Git-Worktrees und neben `serve`.
      --incognito        Start, der nichts aufbewahrt: kein Sitzungsdatensatz, kein
                         Transcript, keine automatischen Speicher-Schreibvorgänge am Ende eines Turns.
                         Was der Lauf erzeugt hat, lebt nur im Prozess;
                         ZUVOR gespeicherte Sitzungen und Notizen bleiben lesbar.
                         Verweigert neben --continue oder --resume, die gespeicherte
                         Sitzungen wieder öffnen.
      --restricted       Start, der keinen Code ausführen kann: Bash, PtyRun, Task,
                         Workflow, ShellStop und mcp_call werden aus
                         jedem Modell-Set für die gesamte Sitzung entfernt, und
                         /permissions kann sie nicht zurücksetzen. Dateitools bleiben,
                         unter der bestehenden Pfadbeschränkung. Akzeptiert auch
                         --restricted=true|false, damit ein Wrapper einen
                         Alias mit dem nackten Flag überstimmen kann. Bleibt bei Neustart erhalten.
      --safe-mode        Start, der alles Vertrauen ignoriert: jeder vertrauenswürdige
                         Projektstamm antwortet als nicht vertrauenswürdig (Hooks, Projekt-
                         MCP und Befehlsshells), keine Bundles werden geladen, und keine
                         fremden Skills, Befehle oder Agenten werden erkannt.
                         Native Einstellungen, Skills und Befehle bleiben. Akzeptiert auch
                         --safe-mode=true|false, um einen
                         Alias zu überstimmen. Bleibt bei Neustart erhalten.
  -h, --help             Diese Hilfe anzeigen
  -v, --version          Installierte Version anzeigen und beenden
      --                 Ende der Optionen: jedes weitere Argument ist positionell,
                         niemals ein Flag

Umgebungsvariablen:
   CANDY_CODE_PROVIDER    Zu verwendender Provider: openai, anthropic, claude-code,
                          sglang, bedrock, vertex, custom
   CANDY_CODE_MODEL       Modellname (überschreibt Provider-Standard; --model gewinnt)
   CANDY_CODE_PERMISSION_MODE
                          Berechtigungsmodus beim Start, überschreibt den
                          Konfigurationsschlüssel permissionMode (--permission-mode gewinnt)
   CANDY_CODE_BACKEND_CMD Shell-Befehl für einen benutzerdefinierten Backend-Adapter, gemäß dem
                          PROSE-Vertrag: erhält JSON-Historie auf stdin, schreibt
                          den Antworttext auf stdout, der wörtlich verwendet wird
                          (nur an den beiden Enden getrimmt, sodass jeder Zeilenumbruch, jede
                          Leerzeile und Einrückung im Inneren erhalten bleibt).
   CANDY_CODE_BACKEND_CMD_STREAM
                          Derselbe Shell-Aufruf unter dem anderen Vertrag, einem TOKEN-
                          STREAM: ein Token pro Zeile, der Zeilenumbruch zwischen zwei
                          Tokens ist Rahmen und wird verworfen, und eine LEERE Zeile ist
                          ein wörtlicher Zeilenumbruch in der Antwort. Der Callback feuert pro
                          Token, wenn der Befehl sie erzeugt, aber die Leseschleife
                          ist synchron, sodass der Bildschirm einmal am Ende neu gezeichnet wird
                          und nicht Token für Token. Nicht austauschbar mit
                          CANDY_CODE_BACKEND_CMD in beide Richtungen — ein Prose-
                          Wrapper, der über diese Variable läuft, kommt mit jedem
                          Zeilenumbruch verloren und jede Leerzeile zu einer zusammengefasst zurück.
                          CANDY_CODE_BACKEND_CMD hat Vorrang, wenn beide gesetzt sind.
                          Für beide gelten nicht gesetzt, leer und nur Leerzeichen als
                          nicht vorhanden.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Tool-Aufrufe eines Turns strikt einzeln ausführen.
                          Gleichzeitige Verteilung ist der Standard und gruppiert nur
                          nicht-mutierende Tools; dies ist der Notausstieg.
                          Als "parallelToolCalls": false speichern in
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Sekunden, die eine gleichzeitige Gruppe laufen darf, bevor ihre
                          Nachzügler beendet und als fehlgeschlagene Aufrufe gemeldet werden
                          (Standard 90, muss 1-119 sein; ein Bruchteil wird gekürzt).
                          Als "parallelToolDeadlineSeconds" speichern.
                          Vorrang: diese Variable, dann der gespeicherte Schlüssel,
                          dann der Standardwert. Ein Wert außerhalb von 1–119 oder einer,
                          der keine Zahl ist, gilt nicht als gesetzt — er
                          fällt auf die nächste Quelle zurück, statt
                          verworfen zu werden.
   CANDY_CODE_ADVISOR_MODEL
                          Das Modell, das das `Advisor`-Tool für eine zweite
                          Meinung konsultiert: eine Tool-freie Vervollständigung,
                          wie jeder andere Aufruf abgerechnet. Anders als bei
                          CANDY_CODE_TITLE_MODEL gibt es keinen günstigen
                          Fallback — nicht gesetzt: Tool nicht verfügbar. Beim Start gelesen.
   CANDY_CODE_TITLE_MODEL Das günstige Modell zum automatischen Benennen einer
                          Sitzung nach dem ersten Austausch; Standard: das des Providers.
   CANDY_CODE_SUMMARY_MODEL
                          Das Modell, das Kompaktierungszusammenfassungen schreibt;
                          Standard: das der Konversation selbst, was den
                          Prompt-Cache wiederverwendet.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual oder off: wie eine Sitzung ihren
                          Kontext bereinigt, wenn /pruning nichts gewählt hat (Standard: auto).
   CANDY_CODE_MAX_COST    Eine Ausgabengrenze für diesen Start, in US-Dollar
                          (Dezimalwerte erlaubt; ein führendes "$" wird akzeptiert;
                          --max-cost hat Vorrang). Ein Turn, der die Grenze
                          überschreitet, wird abgelehnt.
   CANDY_CODE_CONNECT_TIMEOUT
                          Begrenzung der Verbindungsphase, in Sekunden (Dezimalwerte
                          erlaubt; Standard 15,0), für Provider-HTTP-
                          Transports. Begrenzt nur das Herstellen der Verbindung
                          — kein Gesamt-Request-Timeout. Wie lange
                          ein verbundener Streaming-Server für das Senden seiner
                          Antwort-Header braucht, regelt die separate
                          Einstellung streamHeaderTimeoutSeconds.
   CANDY_CODE_SEARCH_ENDPOINT
                          Such-API, die das eingebaute WebSearch-Tool abfragt.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Eine positive ganze Zahl von Tagen: Jeder Start entfernt
                          Sitzungen, die mindestens so lange unberührt waren.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Ehemaliger Upload-Host: /share lädt nie
                          irgendwo hoch. Wenn gesetzt, landet der lokale Export
                          weiterhin, und die Antwort lehnt den Schlüssel lautstark
                          ab und nennt /share serve, das eine selbst gehostete
                          Snapshot-Seite auf dem eigenen candy-code serve veröffentlicht.
   CANDY_CODE_WORKTREES_DIR
                          Basisverzeichnis, unter dem pro Teammitglied Git-
                          Worktrees erstellt werden.
   CANDY_CODE_DISABLE_MOUSE
                          Jeder Wert außer leer oder 0 schaltet die Maus-
                          Verfolgung vollständig aus.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Jeder Wert außer leer oder 0 ignoriert Klick-
                          Gesten, behält aber das Scrollen mit dem Mausrad.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Jeder Wert außer leer oder 0 deaktiviert die
                          Prompt-Cache-Breakpoints des Providers.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Jeder Wert außer leer oder 0 deaktiviert die ausgegrauten
                          Vorschläge für die nächste Nachricht (→ übernimmt) nach jedem Turn.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Jeder Wert außer leer oder 0 deaktiviert das automatische
                          Speichern dauerhafter Fakten als Notizen nach einem Turn, und
                          den Dream-Pass, der das Kompaktierungsjournal
                          in diese einfließen lässt.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Jeder Wert außer leer oder 0 deaktiviert das Lesen und
                          Aktualisieren der LiteLLM-Modelldatenbank, die Modelle ohne
                          eingebaute Werte dimensioniert und bepreist.
   CANDY_CODE_NO_UPDATE_CHECK
                          Jeder Wert außer leer oder 0 deaktiviert die tägliche phar-
                          Release-Prüfung und den Start-Update-Hinweis, den sie liefert;
                          keine Anfrage verlässt den Prozess, und ein veralteter
                          zwischengespeicherter Hinweis wird nicht mehr angezeigt.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Jeder Wert außer leer oder 0 hält die gerankte
                          Symbolkarte aus dem System-Prompt heraus.
   CANDY_CODE_BACKGROUND  light oder dark — erzwingt, was das adaptive Theme
                          über den Terminal-Hintergrund annimmt, und überspringt
                          die OSC 11-Abfrage und COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Jeder Wert außer leer oder 0 gibt SkillLoader's
                          Zeilen pro Überspringung und pro abgelehntes Verzeichnis
                          wieder auf stderr aus.
   CANDY_CODE_DEBUG_COMMANDS
                          Jeder Wert außer leer oder 0 gibt CommandLoader's
                          Zeilen zur Entdeckungs-Ablehnung wieder auf stderr aus.
   CANDY_CODE_DEBUG_RULES Jeder Wert außer leer oder 0 gibt RuleLoader's
                          Zeilen zur Entdeckungs-Ablehnung wieder auf stderr aus.
   CANDY_CODE_DEBUG_STREAM
                          Jeder Wert außer leer oder 0 behält Chat's
                          Zeile "onToken observer threw" auf stderr. Das
                          Detach selbst erfolgt in beiden Fällen.
   CANDY_CODE_SERVER_HOST Die Adresse, an die `serve` bindet (--host hat Vorrang).
   CANDY_CODE_SERVER_PORT Der Port, an den `serve` bindet (--port hat Vorrang).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Kommagetrennte zusätzliche Origins, die `serve` akzeptiert
                          (--allowed-origin hat Vorrang).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Kommagetrennte zusätzliche Hostnamen, die `serve` beantwortet
                          (--allowed-host hat Vorrang).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          Kommagetrennte Client-IPs oder CIDRs, die `serve` zulässt
                          neben Loopback (--allowed-ips hat Vorrang).
   CANDY_CODE_SERVER_WEB_ROOT
                          Verzeichnis, aus dem `serve` die Web-UI ausliefert (--web-root
                          hat Vorrang).
   CANDY_CODE_SERVER_TOKEN
                          Das Token, das `serve` verlangt, statt dem im
                          Statusverzeichnis (mindestens 32 Zeichen; für
                          Container).
   CANDY_CODE_SERVER_DIR  Das Verzeichnis, in dem `serve` Token, Lock,
                          Discovery-Eintrag und Protokoll ablegt (Standard:
                          ~/.candy-code/server; angelegt mit 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Ein Prozess, mit dem `serve` stoppt (--parent-pid hat Vorrang).
   CANDY_CODE_MCP_DISABLE
                          1, true oder yes (Groß-/Kleinschreibung egal) deaktiviert das Projekt-
                          MCP vollständig: .mcp.json wird als nicht vorhanden behandelt, kein
                          Server startet. Nicht gesetzt, 0 oder ein anderer Wert hält
                          MCP aktiviert — anders als die Flag-Variablen,
                          zählen nur diese drei Werte.
   CANDY_CODE_QUIET_LOGS  1, true oder yes (Groß-/Kleinschreibung egal) unterdrückt den
                          error_log()-Nebenkanal prozessweit an seinem einzigen
                          Sink; nicht gesetzt, 0 oder ein anderer Wert lässt die
                          Diagnoseausgabe fließen. Nur beim Start, kein Einstellungsschlüssel.
   CANDY_CODE_REDUCED_MOTION
                          1, true oder yes (Groß-/Kleinschreibung egal) fixiert den Agent-
                          Spinner auf ein statisches Bild — für bewegungsempfindliche
                          und reduzierte-Bewegung-Nutzer. Einmal beim Start gelesen;
                          es gibt keinen Einstellungsschlüssel.
   CANDY_CODE_SD_BASE_URL Basis-URL des A1111-Stil-(sdapi)-Stable-
                          Diffusion-Servers, den der Media-Transport anruft.
                          Vorrang: expliziter Code-Override, dann diese
                          Variable, dann die sd.baseUrl-Einstellung.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Wie generierte Bilder im Terminal dargestellt werden
                          (die Env-Ebene der ui.imageRenderMode-Einstellung; siehe
                          docs/ENVIRONMENT.md für die akzeptierten Werte).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Auf genau 1 setzen, um die candy-code-TESTSUITE
                          als root laufen zu lassen; nicht gesetzt oder ein anderer Wert, die Suite
                          verweigert den Start bei euid 0. Nichts an einem
                          candy-code-Start ändert sich — die Suite ist keine
                          Benutzeroberfläche.
   CANDY_CODE_TOOL_INPUT  Die gesamte Argumentzuordnung des aktuellen User-Script-
                          Tool-Aufrufs, JSON-kodiert, exportiert in den Kind-
                          prozess jedes Laufs eines ~/.candy-code/tools-
                          Tools; die App schreibt es, liest es nie zurück, und
                          niemand setzt es selbst.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Wie viele Spans ein OTLP-Export-Batch trägt
                          (Standard 64, begrenzt auf 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Sekunden, die jeder OTLP-Exportversuch dauern darf
                          (Standard 3; ein nicht-positiver oder fehlerhafter Wert
                          fällt auf den Standard zurück).

   docs/ENVIRONMENT.md listet jede Variable auf, die dieser Build liest, mit ihrer
   vollständigen Spezifikation.

Exit-Codes (One-Shot-Modus und jedes Subkommando):
  0                      Die Eingabe lief und erzeugte eine Antwort, oder das
                         Subkommando antwortete
  1                      Lief und schlug fehl: Das Backend warf (unerreichbarer Host,
                         abgelehnter Schlüssel, Modellfehler) — ein Wiederholungsversuch kann helfen — oder ein
                         Unterbefehl wurde ausgeführt und ist fehlgeschlagen (ein Doctor-Check kam zurück
                         FAIL zurück, ein `session`-Verb fand keine solche Sitzung, eine
                         .mcp.json, der vertraut wird, konnte nicht geparst werden)
  2                      Verwendungs- oder Konfigurationsfehler, nichts wurde versucht
                         und ein Wiederholungsversuch hilft nicht: keine Eingabe angegeben, ein
                         unbekanntes Flag, ein nacktes Argument, das kein
                         bestehendes Verzeichnis benennt (eine Eingabe braucht -p), ein --root,
                         das kein Verzeichnis benennt, eine fehlende composer-
                         autoload.php oder ein ausgewählter Anbieter,
                         der nicht konstruiert werden kann — entweder
                         $CANDY_CODE_PROVIDER oder der Anbieter, der in
                         ~/.candy-code/config.json durch Ctrl+P "Switch model" gespeichert ist.
                         Ein One-Shot-Lauf fällt nie auf den Offline-Echo-
                         Anbieter zurück, wenn ein Anbieter explizit gewählt wurde.
                         Ein Subkommando mit fehlendem oder unbekanntem Operanden
                         (`session`, `mcp bogus`, `completion tcsh`) meldet
                         sich ebenfalls hier.
  130/143/129             TUI: Ein Signal hat die Schleife beendet — 128+N für
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; ein kooperatives
                         Beenden (/exit, q) liefert weiterhin Exit-Code 0.

Beispiele:
  candy-code -p "Erkläre den Unterschied zwischen require und include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Schreibe ein Hello World in Go"
  candy-code run "Schreibe ein Hello World in Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Weitere Informationen finden Sie in der README:
  https://github.com/detain/sugarcraft/tree/master/candy-code

