    'cli.references.unusable' => 'ein `references`-Eintrag konnte nicht gelesen werden — er muss ein Objekt mit einem `path` sein (oder ein einfacher Pfad-String); dieser Eintrag wurde übersprungen.',
    'cli.refuse.bad_mode' => '{source} ist \'{value}\', was kein Berechtigungsmodus ist (erwartet einer von: {valid}). Start verweigert statt auf den permissiven Standard zurückzufallen.',
