    'cli.refuse.config_unreachable' => '{path} ist nicht erreichbar: {reason}, daher ist nicht feststellbar, ob dort eine Berechtigungsrichtlinie konfiguriert ist. Start verweigert, statt mit unbekannter Berechtigungsrichtlinie zu laufen.',
