    'cli.refuse.foreign_owner' => '{path} gehört uid {uid}, nicht dem Konto, unter dem diese Sitzung läuft – die Berechtigungsrichtlinie und Hook-Kette stammen von einem anderen. Start verweigert, statt die Richtlinie eines anderen Kontos auszuführen.',
    'cli.refuse.hook_chain' => '{error} Start verweigert, statt mit einer Hook-Kette zu laufen, die nicht die konfigurierte ist.',
    'cli.refuse.hooks_unreachable' => '{path} ist nicht erreichbar: {reason}, daher ist nicht feststellbar, ob dort Hooks konfiguriert sind. Start verweigert, statt mit unbekannter Hook-Kette zu laufen.',
    'cli.refuse.keybindings' => 'Die Einstellung keybindings ist unbrauchbar: {reason}. Schlüssel entfernen, um mit den mitgelieferten Belegungen zu laufen (die /keys-Referenz nennt sie). Start verweigert, statt mit Tastenbelegungen zu laufen, die du nicht erhalten hast.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST ist \'{value}\', das ist keine Ausgabengrenze. Erwartet wird eine positive Zahl in US-Dollar (Dezimalbruch erlaubt, führendes $ akzeptiert), z. B. 5 oder $2.50. Null und negative Werte werden abgelehnt, statt als "kein Limit" gelesen zu werden, da sie das Gegenteil ausdrücken; ein zu großer Wert (1e309, d. h. unendlich) wird abgelehnt, da er eine Grenze setzen würde, die nie greift. Variable entfernen für kein Limit. Start verweigert, statt ohne Limit zu laufen, obwohl eine Grenze angefordert wurde.',
    'cli.refuse.max_cost_flag' => '--max-cost ist \'{value}\', das ist keine Ausgabengrenze. Erwartet wird eine positive Zahl in US-Dollar (Dezimalbruch erlaubt, führendes $ akzeptiert), z. B. 5 oder $2.50. Null und negative Werte werden abgelehnt, statt als "kein Limit" gelesen zu werden, da sie das Gegenteil ausdrücken; ein zu großer Wert (1e309, d. h. unendlich) wird abgelehnt, da er eine Grenze setzen würde, die nie greift. Flag weglassen für kein Limit. Start verweigert, statt ohne Limit zu laufen, obwohl eine Grenze angefordert wurde.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd in den Einstellungen ist {value}, das ist keine Ausgabengrenze. Erwartet wird eine positive Zahl in US-Dollar, z. B. 5 oder 2.5. Schlüssel entfernen für kein Limit. Start verweigert, statt ohne Limit zu laufen, obwohl eine Grenze angefordert wurde.',
    'cli.refuse.max_turns_flag' => '--max-turns ist \'{value}\', das ist keine Schrittgrenze. Erwartet wird eine positive ganze Zahl von Tool-Loop-Schritten, z. B. 8. Null wird abgelehnt, statt als "kein Limit" gelesen zu werden, da sie das Gegenteil ausdrückt; ein zu großer Wert wird abgelehnt, da er eine Grenze setzen würde, die nie greift. Flag weglassen, um auf die Einstellung maxToolSteps zu verweisen. Start verweigert, statt ohne Limit zu laufen, obwohl eine Grenze angefordert wurde.',
    'cli.refuse.no_home' => 'Dieser Prozess kann nicht bestimmen, welches Home-Verzeichnis dir gehört ($HOME ist nicht gesetzt, $USERPROFILE ist nicht gesetzt, und es gibt keinen passwd-Eintrag für seine uid), daher können die Berechtigungsrichtlinie und Hook-Kette in ~/.candy-code nicht gefunden werden. Start verweigert, statt eine davon aus einem weltweit beschreibbaren Fallback-Verzeichnis zu lesen — exportiere HOME auf das Konto, dem diese Sitzung gehört.',
    'cli.refuse.no_project_root' => 'Projekt-Root kann nicht bestimmt werden — das Arbeitsverzeichnis des Prozesses ist nicht verfügbar (gelöscht oder unlesbar). --root <dir> übergeben.',
    'cli.refuse.not_searchable' => '{dir} ist von diesem Prozess nicht durchsuchbar',
    'cli.refuse.project_settings_unusable' => '{path} konnte nicht auf permissionRules gelesen werden ({reason}). Start verweigert, statt mit unbekannter Berechtigungsrichtlinie zu laufen.',
    'cli.refuse.world_writable' => '{path} ist von jedem Konto auf diesem Rechner beschreibbar, daher stammen die Berechtigungsrichtlinie und Hook-Kette nicht von diesem Benutzer. Start verweigert, statt eine Richtlinie auszuführen, die jeder geschrieben haben könnte — `chmod o-w {path}`.',
