    'cli.selfupdate.composer_mode' => 'candy-code: self-update ersetzt eine phar-Installation, und diese Kopie wurde über Composer installiert — hier gibt es kein phar zum Austauschen. Aktualisieren mit: {command} (eine globale Installation führt stattdessen `composer global update sugarcraft/candy-code` aus).',
    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update ersetzt eine phar-Installation, und diese Kopie ist das Paket sugarcraft/candy-code, installiert als Composer-Root — hier gibt es kein phar zum Austauschen, und ein Root-Paket kann sich nicht über seinen eigenen Abhängigkeitsbefehl aktualisieren. Aktualisieren mit: {command} (der Clone zieht den neuen Quellcode und baut dann den vendor-Baum neu).',
