    'cli.selfupdate.sig.sidecar_invalid' => 'candy-code: {asset} verifiziert den {sidecar}-Sidecar des heruntergeladenen {phar} nicht gegen den festgelegten Release-Schlüssel. Nichts wurde ausgetauscht.',
