    'cmd.mcp-auth.disable.done' => '✓ `{server}` für diese Sitzung deaktiviert — Aufrufe werden ab der nächsten Runde abgelehnt; das modellseitige Verzeichnis wird nicht neu abgeleitet (Cache-Regel), daher bleiben seine Tools bis zum Neustart gelistet.',
    'cmd.mcp-auth.disable.no-client' => 'Kein MCP-Client in dieser Sitzung — nichts zu deaktivieren (keine `.mcp.json` beim Start vertraut).',
