    'cmd.mcp-auth.disable.unknown' => '! `{server}` ist kein deklarierter MCP-Server dieser Sitzung — `/mcp list` zeigt die Namen.',
    'cmd.mcp-auth.disable.usage' => 'Verwendung: /mcp disable <server> [--persist]',
    'cmd.mcp-auth.empty' => "Keine gespeicherten MCP-Zugangsdaten.\n\nZugangsdaten sind nur für Server, die OAuth-Login verlangen; ein\ndeklarierter http-Server, der keine braucht, läuft allein über seine \"url\".\nServer selbst werden unter \"mcpServers\" in\n<project>/.mcp.json — Anleitung: docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ `{server}` für diese Sitzung aktiviert — Sitzungsablehnungen werden ab der nächsten Runde aufgehoben; Aufrufe werden nur dort wieder geroutet, wo das Start-Routing den Namen bereits erlaubt.',
    'cmd.mcp-auth.enable.no-client' => 'Kein MCP-Client in dieser Sitzung — nichts zu aktivieren (keine `.mcp.json` beim Start vertraut).',
    'cmd.mcp-auth.enable.not-armed' => '! `{server}` wurde für diese Sitzung nicht deaktiviert.',
    'cmd.mcp-auth.enable.persist-none' => 'Kein disabledMcpServers-Eintrag für `{server}` zum Entfernen.',
    'cmd.mcp-auth.enable.persist-removed' => '`{server}` aus der Benutzerliste disabledMcpServers entfernt; der Start lehnt es nicht mehr ab.',
    'cmd.mcp-auth.enable.unknown' => '! `{server}` ist kein deklarierter MCP-Server dieser Sitzung — `/mcp list` zeigt die Namen.',
    'cmd.mcp-auth.enable.usage' => 'Verwendung: /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ Registrierung fehlgeschlagen: {error}',
    'cmd.mcp-auth.heading' => '**MCP Servers**',
    'cmd.mcp-auth.login-armed' => "↻ MCP-Login für `{server}` gestartet — warte auf den Browser-Link.\n\nDer Kindprozess bindet einen Loopback-Port; abschließen im Browser, während die TUI responsiv bleibt. Der MCP-Client dieser Sitzung hat seinen Speicher beim Start memoisiert, daher wirkt das Token erst beim NÄCHSTEN Start; `/mcp list` zeigt die Zugangsdaten, sobald sie gespeichert sind.",
    'cmd.mcp-auth.login-busy' => '! Ein Login für `{server}` läuft bereits — diesen zuerst abschließen oder abbrechen (URL und Status stehen im Transkript oben).',
    'cmd.mcp-auth.login-code-delivered' => '✓ Der Callback wurde an den wartenden Login für `{server}` übergeben — der Kindprozess schließt den Austausch dort ab, und das Ergebnis erscheint im Transkript.',
    'cmd.mcp-auth.login-code-refused' => '! MCP-Login-Callback für `{server}` konnte nicht übergeben werden: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "der Listener des wartenden Logins antwortete nicht",
    'cmd.mcp-auth.login-code-reason-host' => 'nur die Loopback-Hosts `127.0.0.1` und `localhost` werden akzeptiert',
    'cmd.mcp-auth.login-code-reason-noslot' => 'kein Login für diesen Server wartet derzeit auf diesem Host',
    'cmd.mcp-auth.login-code-reason-port' => 'der Port stimmt nicht mit dem vom wartenden Login angekündigten Callback-Port überein',
    'cmd.mcp-auth.login-code-reason-scheme' => 'die Callback-URL muss das einfache `http`-Schema verwenden, an das der Login-Listener bindet',
    'cmd.mcp-auth.login-code-reason-shape' => 'das Format ist `/mcp login <server> --code <callback-url>` mit genau einer URL',
    'cmd.mcp-auth.login-done' => '✓ MCP-Login für `{server}` abgeschlossen (Exit {code}). Tokens werden beim NÄCHSTEN Start angehängt — neue Sitzung starten, damit das Grant Requests begleitet; `/mcp list` aktualisiert das Panel.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ MCP-Login für `{server}` endete mit {code}, ohne Tokens zu speichern.

Die letzten Zeilen des Kindprozesses stehen oben; derselbe Ablauf in einer Shell (`candy-code mcp auth login {server}`) gibt den vollständigen Fehler aus und ist der Ort zum Debuggen von Endpoint- oder Port-Problemen.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ MCP-Login-Kindprozess für `{server}` konnte nicht gestartet werden.\n\nShell-Form direkt ausführen: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "Interaktiver Login ist ein Shell-Befehl, keine Chat-Runde:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nEs führt den OAuth-Authorization-Code-Flow mit PKCE aus: Dein Browser\nsendet den Code an einen Loopback-Listener in der Shell, und die gespeicherten\nTokens werden ab dem nächsten Start an passende http-Server angehängt.",
    'cmd.mcp-auth.login-no-entry' => "✗ Eigener Einstiegspunkt dieses Programms konnte nicht gefunden werden, um `mcp auth login {server}` zu forken.\n\nFühre die Shell-Form direkt aus: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ MCP-Login für `{server}` auf dem SERVER-Host gestartet — der Link erscheint unten; öffne ihn in einem Browser auf deinem eigenen Rechner. Dein Browser kann den Loopback-Listener des Servers nicht direkt erreichen: Wenn eine Verbindungsfehler-Seite erscheint, kopiere deren Adresse und sende `/mcp login {server} --code <diese-url>`, um den Callback an den wartenden Login zu übergeben. Tokens werden beim NÄCHSTEN Start angehängt; `/mcp list` zeigt die Zugangsdaten, sobald sie gespeichert sind.",
    'cmd.mcp-auth.login-url' => '→ Öffne diese URL, um `{server}` zu autorisieren:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! Keine Zugangsdaten für `{server}` gefunden.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` erfolgreich registriert
Client-ID: `{client}`
Anfragen an einen http-MCP-Server mit exakt dieser URL tragen dieses Token automatisch, vor Ablauf erneuert; Server, die vor diesem Befehl gestartet wurden, übernehmen es beim nächsten Start.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Verwendung: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` meldet jetzt, dass ein OAuth-Login erforderlich ist.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` wird durch ein Deny-Muster abgelehnt.',
    'cmd.mcp-auth.reconnect.drifted' => "MCP-Konfiguration seit dem Start geändert — Reconnect verweigert. Ein Reconnect startet die Server exakt so, wie `.mcp.json` sie jetzt enthält, während diese Sitzung gegen die beim Start vertrauten Bytes zugelassen wurde; das Starten abgedrifteter Einträge würde Server ausführen, die die Zulassungsentscheidungen nie gesehen haben. Starte die Sitzung neu, um die Änderung anzuwenden; das ist der einzige Anwendungsweg.",
    'cmd.mcp-auth.reconnect.error' => 'Start fehlgeschlagen: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**MCP-Server neu verbunden**',
    'cmd.mcp-auth.reconnect.no-client' => 'Kein MCP-Client in dieser Sitzung — nichts neu zu verbinden (keine `.mcp.json` war beim Start vertraut).',
    'cmd.mcp-auth.reconnect.none' => 'keine Server für diese Sitzung gestartet',
    'cmd.mcp-auth.reconnect.refused' => '! `{server}` wurde bei der Zulassung abgelehnt (Trust-Pin-Abweichung oder unbekannter Eintrag).',
    'cmd.mcp-auth.reconnect.state.down' => 'down',
    'cmd.mcp-auth.reconnect.state.starting' => 'startet',
    'cmd.mcp-auth.reconnect.state.up' => 'up',
    'cmd.mcp-auth.reconnect.tool-drift' => 'bietet {now} Tools an; diese Sitzung wurde mit {was} aufgebaut — die modellseitige Tool-Liste wird mitten in der Sitzung nicht neu abgeleitet, starte eine neue Sitzung, um sie zu übernehmen',
    'cmd.mcp-auth.reconnect.unknown' => 'Diese Sitzung hat keinen Start-Digest für `.mcp.json` aufgezeichnet, daher kann ein Reconnect nicht nachweisen, dass die Konfiguration noch die Bytes enthält, von denen der Start ausging — verweigert, Neustart ist der einzige Anwendungsweg.',
    'cmd.mcp-auth.removed' => '✓ Zugangsdaten für `{server}` entfernt',
    'cmd.mcp-auth.status.active' => '● aktiv',
    'cmd.mcp-auth.status.expired' => '○ abgelaufen',
    'cmd.mcp-auth.status.expiring' => '● läuft bald ab',
    'cmd.mcp-auth.status.none' => '○ keine Zugangsdaten',
    'cmd.mcp-auth.undiscovered' => "! OAuth-Endpunkte konnten für `{server}` nicht ermittelt werden.\n\nBitte gib sie explizit an:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nNichts zu entdecken bedeutet normalerweise nichts zu registrieren: Ein\nServer, der keinen Login braucht, läuft allein aus seiner \"url\", sobald\ner in .mcp.json deklariert ist (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Unbekannter Unterbefehl \'{sub}\'. Verwende: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Verwendung:\n  mcp auth list                    — registrierte Server auflisten\n  mcp auth add <server> [reg-url] [token-url]  — OAuth-Zugangsdaten für einen Server speichern\n  mcp auth remove <server>         — Zugangsdaten eines Servers entfernen\n  mcp auth login <server>          — den Shell-Befehl für interaktiven Login ausgeben\n  /mcp reconnect                   — deklarierte Server neu starten, nur solange .mcp.json noch dem Startzustand entspricht\n  /mcp enable <server> [--persist]   — die Ablehnung eines deklarierten Servers in dieser Sitzung aufheben\n  /mcp disable <server> [--persist]  — Aufrufe eines deklarierten Servers in dieser Sitzung ablehnen",
    'cmd.mcp.description' => 'MCP-Server-Auth verwalten (list/add/remove; login gibt den CLI-Befehl aus) und Sitzung enable/disable',
    'cmd.mcp.hint' => '<list|add|remove|login|reconnect|enable|disable> [server]',
