    'sandbox.hook.not_run' => 'Nicht ausgeführt: Der Hook `{hook}` wird durch sandboxScope in die `{mode}`-Sandbox eingegrenzt, aber die {name}-Sandbox kann auf diesem Host nicht starten ({reason}). Nichts wurde ausgeführt, weder in der Sandbox noch außerhalb. Dem Nutzer mitteilen: Er kann {name} beheben ({remedy}) oder bashSandbox auf "off" setzen.',
    'sandbox.lsp.not_started' => 'Nicht gestartet: Der `{language}`-Sprachserver ({command}) wird durch sandboxScope in die `{mode}`-Sandbox eingegrenzt, aber die {name}-Sandbox kann auf diesem Host nicht starten ({reason}). Nichts wurde gestartet, weder in der Sandbox noch außerhalb. Dem Nutzer mitteilen: Er kann {name} beheben ({remedy}), bashSandbox auf "off" setzen oder diesen Server mit `"sandbox": false` in seinem eigenen `lsp`-Eintrag ausnehmen.',
    'sandbox.mcp.not_started' => 'Nicht gestartet: Der MCP-Server `{server}` wird durch sandboxScope in die `{mode}`-Sandbox eingegrenzt, aber die {name}-Sandbox kann auf diesem Host nicht starten ({reason}). Nichts wurde gestartet, weder in der Sandbox noch außerhalb. Dem Nutzer mitteilen: Er kann {name} beheben ({remedy}), bashSandbox auf "off" setzen oder ihn mit `"sandbox": false` im Benutzer-Eintrag ausnehmen.',
    'sandbox.mcp.opt_out_ignored' => 'Ignoriert: Das `"sandbox": false`-Opt-out für MCP-Server {servers} stammt nicht aus der Benutzereinstellungsdatei — nur die Benutzer-Ebene kann einen stdio-Server aus der sandboxScope-Sandbox ausnehmen. Der/die Server bleibt/bleiben wie eingegrenzt in der Sandbox.',
    'sandbox.runner.skipped' => 'Übersprungen: Der {scope}-Lauf wird durch sandboxScope in die `{mode}`-Sandbox eingegrenzt, aber die {name}-Sandbox kann auf diesem Host nicht starten ({reason}). Nichts wurde ausgeführt, weder in der Sandbox noch außerhalb. Dem Nutzer mitteilen: Er kann {name} beheben ({remedy}) oder bashSandbox auf "off" setzen.',
