    'send.session.subagent' => 'Ein Sub-Agent kann keine andere Sitzung anschreiben; `session:`-Ziele sind für den Agenten der Sitzung selbst — schreibe deinen Eltern-Agenten an, oder berichte und lass deinen Eltern-Agenten für die Konversation sprechen.',
