    'chat.command.error' => '**Error:** {error}',
    'chat.compact.idle_advisory' => 'Diese Sitzung ist seit über einer Stunde im Leerlauf und ist auf ~{tokens} geschätzte Tokens angewachsen, über ihr {limit}-Token-Kontextfenster. Führe /compact aus, um den Kontext vor dem Fortsetzen zu verkleinern. Eine weitere Nachricht zu senden wird sie nicht unverändert senden: Der nächste Durchlauf liegt über der automatischen Kompaktierungsstufe, daher werden ältere Wechsel zuerst zusammengefasst, und der Durchlauf wird komplett abgelehnt, wenn das nicht genug freigibt.',
    'chat.compact.idle_auto_scheduled' => 'Automatische Leerlauf-Kompaktierung: Die Sitzung lag über dem Leerlauf-Fenster mit dem Transkript über ihrer Kompaktierungsstufe (~{tokens} geschätzte Tokens gegenüber einem {limit}-Token-Fenster), daher ging die Zusammenfassungsanfrage unbeaufsichtigt raus. Die Faltung landet im nächsten Durchlauf; nichts wird doppelt berechnet und keine Antwort an jemanden gesendet.',
    'chat.compact.idle_folded' => 'Kompaktiert während des Leerlaufs: ~{before} geschätzte Tokens wurden zu ~{after}. `compaction.idleAuto` führte die automatische Stufe aus, während die Sitzung unberührt lag, daher sind die von ihr verdichteten Wechsel jetzt Zusammenfassungen.',
