    'chat.session.read_only' => 'Sitzung {session} ist in einem anderen candy-code{holder} geöffnet, daher ist dieses Fenster schreibgeschützt: Was hier getippt wird, geht weder an das Modell noch wird es in dieser Sitzung gespeichert. Tippe /branch, um sie in eine neue Sitzung abzuzweigen, die dieses Fenster besitzt, und arbeite dort weiter, oder schließe das andere Fenster und dieses wird automatisch beschreibbar.',
    'chat.session.resumed' => '_Sitzung {session} fortgesetzt._',
