    'chat.sessions.no_store_new' => 'Sitzungsspeicher nicht konfiguriert — neue Sitzungen können nicht aufgezeichnet werden. Ein einfacher `candy-code`-Start hat immer einen; ein Host-Integrations-Build muss ihn anhängen.',
