    'chat.spend.crossed_by_summarization' => 'Die Zusammenfassung, hinter der diese Runde wartete, hat die Obergrenze erreicht; dieser Aufruf ging vor dem Erreichen der Obergrenze raus und wird berechnet. Deine Eingabe steht im Transkript oben, ungesendet.',
