    'chat.theme.file_refused' => 'Theme \'{theme}\' ist unter \'{directory}\' gelistet, aber sein realer Pfad liegt nicht innerhalb dieses Verzeichnisses, daher wurde die Datei abgelehnt und nie gelesen; stattdessen wird das Standard-Theme verwendet.',
    'chat.theme.set' => 'Theme auf \'{theme}\' gesetzt.',
    'chat.title.error' => '**Fehler:** {error}',
    'chat.turn.loop_guard' => 'Diese Runde wurde durch den Wiederholungs-Schleifenschutz beendet: Das Modell rief {tool} {count} Mal mit denselben Argumenten auf und erhielt jedes Mal dasselbe Ergebnis. Die Antwort oben beschreibt, wo es stoppte. Weise es auf einen anderen Ansatz hin, oder sage `continue`, sobald sich etwas geändert hat.',
    'chat.turn.output_limit' => 'Der Anbieter stoppte diese Antwort an seinem Ausgabelimit, daher kann der Text oben mitten im Gedanken enden. Erhöhe `maxOutputTokens` in ~/.candy-code/config.json für eine längere einzelne Antwort, oder frage den Rest in deiner nächsten Nachricht an.',
    'chat.turn.steps_exhausted' => 'Diese Runde hat alle ihre Tool-Schritte aufgebraucht, bevor die Arbeit erledigt war, daher beschreibt die Antwort oben, wo es stoppte — was fertig ist und was bleibt — keine fertige Antwort. Sage `continue`, um dort fortzusetzen, oder erhöhe die Obergrenze für längere agentische Runden — ein --max-turns-Flag beim Start überstimmt die `maxToolSteps`-Einstellung in ~/.candy-code/config.json, also erhöhe, was gerade gilt.',
    'chat.turn.unpriced_model' => 'Diese App hat keinen Preis für das Modell `{model}` hinterlegt, daher wurde diese Runde mit $0.00 als Untergrenze berechnet, nicht als kostenloser Aufruf — Ausgabensummen und die Ausgabengrenze werden unterzählt, bis ein Tarif existiert. Deklariere einen unter `modelPrices` in ~/.candy-code/config.json (USD pro 1M Tokens, Schlüssel `input` und `output`), um es zu bepreisen.',
    'chat.verbose.failed' => 'Ausführlich-Umschaltung abgelehnt: {error}',
