    'chat.workflow.cancelled' => '_Workflow abgebrochen: Stoppe seine Agenten. Sein Bericht folgt._',
    'host.agents.accept.bad_name' => '`{name}` ist kein Entwurfsname. Ein Entwurf ist eine Datei direkt im Entwurfsverzeichnis, und du übergibst seinen Namen — Kleinbuchstaben, Ziffern, Punkte, Unterstriche und Bindestriche — an /agents accept.',
    'host.agents.accept.exists' => 'Ein Preset namens {name} existiert bereits unter {dir}/, und /agents accept überschreibt nie ein aktives Preset. Lösche oder benenne dieses Preset zuerst um, oder erstelle mit /agents new einen Entwurf unter einem anderen Namen.',
    'host.agents.accept.frontmatter' => 'Entwurf {name} hat keinen Frontmatter-Block, der als Mapping geparst werden kann, daher wurde er nicht hochgestuft. Führe /agents new erneut aus, oder korrigiere die Datei und akzeptiere sie erneut.',
    'host.agents.accept.missing' => 'Kein Entwurf namens {name} unter {dir}/. Führe /agents new aus, um einen zu erstellen, oder /agents proposed, um die Entwürfe aufzulisten.',
    'host.agents.accept.mode' => 'Entwurf {name} deklariert `permissionMode: {mode}`, was keiner der Modi dieses Ports ist. Deklariere einen von: {modes} — oder lass den Schlüssel weg für `default`.',
    'host.agents.accept.moved' => 'Entwurf {name} ist jetzt {path} — das Roster der nächsten Sitzung lädt es als Projekt-Preset.',
    'host.agents.accept.policy' => 'Richtlinie, die dieser Entwurf deklariert (wörtlich vor dem Verschieben ausgegeben):',
    'host.agents.accept.policy_line' => '  - {key}: {value}',
    'host.agents.accept.self_grant' => '**Hinweis:** `{mode}` ist eine Selbsterteilung — das hochgestufte Preset startet Läufe mit einer entsprechend breiteren Berechtigungsfläche als eine einfache Sitzung. Das Hochstufen hier ist deine Zustimmung; der Entwurf selbst konnte sie nicht erteilen.',
    'host.agents.accept.type' => 'Entwurf {name} deklariert `{key}` als einen Wert, den der Preset-Reader nicht typisieren kann — er erwartet einen String oder eine Liste von Strings.',
    'host.agents.accept.unknown' => 'Entwurf {name} deklariert `{key}`, einen Schlüssel, auf den kein Preset-Reader reagiert{hint}. Entferne ihn oder korrigiere die Schreibweise; /agents accept stuft nur Dateien hoch, deren Schlüssel dieser Port liest.',
    'host.agents.error' => 'Der /agents-Entwurfsbefehl ist fehlgeschlagen: {error}',
    'host.agents.new.dispatched' => 'Der Agent wird gebeten, ein Preset aus dieser Konversation zu entwerfen; er schreibt nur die Entwurfsebene, und nichts wird hochgestuft, bis du /agents accept ausführst.',
    'host.agents.proposed.heading' => 'Vorgeschlagene Agent-Entwürfe:',
    'host.agents.proposed.none' => 'Keine Entwürfe warten unter {dir}/. Führe /agents new aus, damit der Agent einen aus dieser Konversation erstellt.',
    'host.agents.usage' => 'Verwendung: /agents [list|<name>|use <preset|default>|new <focus>|proposed|accept <name>]',
    'host.agents.not_configured' => 'Agent-Manager nicht konfiguriert — keine Sub-Agent-Laufzeitumgebung ist an diesen Start angehängt, daher kann /agents keine Agenten starten oder überwachen. Ein einfacher `candy-code`-Start hat immer eine; ein Host-Integrations-Build muss sie anhängen.',
    // C-AGT-4.b: the `use` verb. Soft-appended after the block's last row;
