    'host.agents.use_default' => 'Zurück zum Standard der einfachen Sitzung — nichts, was ein vorheriger /agent-Einsatz eingeschränkt hat, bleibt angewendet.',
    'host.agents.use_switched' => '{name} ist jetzt der primäre Agent dieser Sitzung — seine Tools, sein Modell und seine Berechtigungsuntergrenze gelten, bis du zurückwechselst; ein Neustart nutzt den Standard der einfachen Sitzung.',
    'host.agents.use_turn_running' => 'Eine Runde läuft — der primäre Agent wechselt zwischen Runden, wie ein Berechtigungsmodus-Wechsel.',
