    'host.bg.active' => 'Aktive Hintergrund-Sitzungen: {sessions}',
    'host.bg.backgrounded' => 'Als {id} (\'{name}\') in den Hintergrund verschoben — nutze /agents für den Status, /bg stop {id} zum Abbrechen.',
