    'host.bg.not_configured' => 'Hintergrund-Sitzungen nicht konfiguriert — dieser Start kann keine Aufgaben abseits des Vordergrunds ausführen. Ein einfacher `candy-code`-Start hat immer den Supervisor; ein Host-Integrations-Build muss einen anhängen, bevor /bg und /fork funktionieren.',
    'host.bg.start_failed' => 'Hintergrund-Sitzung \'{name}\' konnte nicht gestartet werden: {error}',
