    'host.bg.usage' => 'Verwendung: /bg <task>',
    'host.command_shell.bundle_refused' => '[!`{command}` wurde nicht ausgeführt: /{name} kam aus einem Plugin-Bundle, einem Paket, das jemand anderes gepackt hat. Eine Bundle-Zeile verweigert Shell-Formen unabhängig davon, unter welcher Ebene sie installiert wurde — kein lokales Recht entsperrt eine, und ein pro-Herkunft-Opt-in ist das geplante Nachfolgefeature — der Rest des Befehls wurde gesendet.]',
    'host.command_shell.mcp_refused' => '[!`{command}` wurde nicht ausgeführt: /{name} ist ein MCP-Prompt, das von einem Server abgerufen wurde, Text, der über die Leitung kam. Ein abgerufener Body verweigert Shell-Formen unabhängig davon, was dieses Projekt vertraut — kein lokales Recht entsperrt eine, und ein pro-Herkunft-Opt-in ist das geplante Nachfolgefeature — der Rest des Prompts wurde gesendet.]',
    'host.loop.not_configured' => 'Zeitpläne nicht für diese Sitzung konfiguriert — /loop hat keine Uhr, auf der es laufen kann. Ein einfacher `candy-code`-Start trägt immer eine; ein Host-Integrations-Build muss eine bereitstellen.',
    'host.loop.usage' => 'Verwendung: /loop <interval> <prompt> — Intervall wie 90s, 15m, 2h, 1d (Untergrenze 10s). Die Schleife lebt in diesem Prozess; /schedules listet sie, /schedules delete beendet sie.',
    'host.loop.bad_interval' => 'Kein Intervall: {interval}. Nutze Sekunden (60), oder ein Suffix: 90s, 15m, 2h, 1d.',
    'host.loop.registered' => 'Schleife {name}: alle {every} — `{prompt}` wird hier als Runde eingereiht (erster Auslöser ein Intervall entfernt). Endet mit dem Prozess, oder /schedules delete {name}.',
    'host.loop.queued' => "Schleife '{name}' ist fällig: Ihr Prompt wird für diese Sitzung eingereiht.",
    'host.output_style.arity' => '/output-style erwartet einen Stilnamen oder `off`; gelesen als `{args}`.',
    'host.output_style.available' => 'Verfügbare Stile: {names}',
    'host.output_style.cleared' => 'Kein Ausgabestil ist jetzt aktiv — der Prompt läuft ab der nächsten Runde ohne Stil-Regelwerk.',
    'host.output_style.column_source' => 'Quelle',
    'host.output_style.column_state' => 'Status',
    'host.output_style.column_style' => 'Stil',
    'host.output_style.empty' => "Keine Ausgabestile gefunden.\nEin Stil ist eine Markdown-Datei in ~/.candy-code/styles/ (oder .candy-code/styles/ im Projekt),\nbenannt nach ihrem Dateinamen: terse.md wird mit /output-style terse ausgewählt.",
    'host.output_style.footer' => "/output-style <name> wählt einen Stil aus; genau einer ist aktiv, und ein\nWechsel löscht den vorherigen. /output-style off leert den Slot. `off` ist ein\nreserviertes Wort — eine Datei namens off.md kann nicht ausgewählt werden. Ein Stil, der durch sein\neigenes Frontmatter (`enabled: false`) deaktiviert wurde, bleibt aus dem Prompt, unabhängig vom Namen.",
    'host.output_style.heading' => 'Ausgabestile (nur Sitzung — hier wird nichts in die Konfiguration geschrieben):',
    'host.output_style.matches' => ' (dieser Name entspricht {count} Stil-Dateien — alle sind aktiv)',
    'host.output_style.nothing_active' => 'Kein Ausgabestil war aktiv — nichts zu löschen.',
    'host.output_style.self_disabled' => "\nSein eigenes Frontmatter sagt enabled: false, daher bleibt es aus dem Prompt, bis diese Zeile geändert wird — die Auswahl konnte eine Datei, die sich selbst deaktiviert hat, nicht überschreiben.",
    'host.output_style.set' => "Stil {name}: AKTIV für diese Sitzung.{note}\nEs wirkt im Prompt ab der nächsten Runde; ein vorheriger Stil ist raus — genau einer ist aktiv.",
    'host.output_style.state_active' => 'aktiv',
    'host.output_style.state_off' => 'off',
    'host.output_style.state_off_frontmatter' => 'off (Frontmatter)',
    'host.output_style.unknown' => 'Unbekannter Ausgabestil: {name}',
    'host.doctor.heading' => 'Installationsprüfung (`/doctor`)',
    'host.doctor.column_status' => 'Status',
    'host.doctor.column_check' => 'Prüfung',
    'host.doctor.column_detail' => 'Detail',
    'host.schedules.not_configured' => 'Zeitpläne in dieser Sitzung nicht konfiguriert.',
    'host.schedules.usage' => 'Verwendung: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. Einträge liegen in ~/.candy-code/schedules.json; /schedules add erstellt einen über die Factory-Grenzen des Schedule-Tools, /loop registriert einen temporären.',
    'host.schedules.none' => 'Keine Zeitpläne. /schedules add <name> <interval> <prompt> erstellt einen über dieselben Grenzen wie das Schedule-Tool, oder schreibe einen Eintrag in ~/.candy-code/schedules.json (`name`, `every` in Sekunden, `prompt`, `root` — das Projektverzeichnis, in dem er feuert; optional `provider`, `permissionMode` (Bypass-Klassen-Schreibweisen werden abgelehnt; weglassen für die nicht-interaktive Untergrenze), `enabled`, `timeoutSeconds`, `kind` (`task` antwortet, `heartbeat` kann stumm bleiben)), oder /loop einen für diese Sitzung. docs/SCHEDULES.md ist das Format.',
    'host.schedules.row' => '{state}{kind}{name} — alle {every}, nächster {next} @ {root}: {prompt}',
    'host.schedules.unbound' => 'ungebunden',
