    'host.schedules.deleted_loop' => 'Schleife {name} entfernt (nur dieser Prozess — sie war nie auf der Festplatte).',
    'host.schedules.persist_failed' => 'Zeitplan {name} in dieser Sitzung geändert, konnte aber nicht zurückgeschrieben werden: {error}',
    'host.schedules.added' => 'Zeitplan {name}: alle {every} — `{prompt}` feuert in diesem Projekt als überwachter Hintergrundlauf (erster Auslöser ein Intervall voraus, nächster {next}). Erstellt über die Factory des Schedule-Tools: Modus bei Erstellung festgelegt, zählt gegen das Modell-Limit pro Projekt, an diese Root gebunden. `/schedules delete {name}` entfernt ihn.',
    'host.schedules.add_usage' => 'Verwendung: /schedules add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat]',
