    'host.spend.lower_bound' => ' Mindestens ein Modell, das in dieser Sitzung verwendet wurde, hat keinen hinterlegten Preis, daher ist dies eine UNTERGRENZE: deklariere Tarife unter `modelPrices` in ~/.candy-code/config.json, um sie abzurechnen.',
    'host.spend.mid_turn' => '_Ausgabenlimit mitten im Durchlauf erreicht: abgebrochen nach Provider-Aufruf {calls} — {spent} des ${cap}-Limits verbraucht. Keine weiteren Aufrufe in diesem Durchlauf; /budget erhöht das Limit._',
