    'host.spend.status_unreported' => 'Bisherige Ausgaben: von diesem Provider nicht gemeldet ({cap}). Gestreamte Durchläufe und selbst gehostete Provider melden oft gar keine Nutzung, und eine nicht gemeldete Sitzung wird vom Limit nie blockiert.',
    'host.spend.usage' => 'Verwendung: /budget <betrag> begrenzt die Ausgaben dieser Sitzung (z. B. /budget 5 oder /budget $2.50), /budget off löscht das Limit, /budget allein zeigt den aktuellen Stand. Der Betrag muss eine reelle Zahl größer als null sein — ein Limit von 0 und kein Limit sind gegensätzliche Anforderungen, daher wird `0` abgelehnt statt geraten, und ein zu großer Wert (`1e309`, also unendlich) wird abgelehnt statt als Limit akzeptiert, das nie auslösen würde.',
    'host.turn.bang_refused' => '`{command}` wurde nicht ausgeführt: {reason}.',
