    'host.turn.empty_custom_command' => '{draft} ist eine Befehlsdatei, deren Template sich zu nichts expandierte — meist ein Rumpf, der nur $ARGUMENTS oder $1 enthält, ohne Argumente aufgerufen. Nichts wurde gesendet: eine leere Eingabe kostet einen Durchlauf und teilt dem Modell nichts mit. Gib Argumente mit, oder gib der Datei einen eigenständigen Rumpf.',
