    'keys.dirpicker.start' => 'Sitzung im angezeigten Verzeichnis starten',
    'keys.dirpicker.close' => 'Abbrechen — nichts wird gestartet',

    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` liest sich wie ein Slash-Befehl, kein Filter — Enter würde hier den besten Treffer fortsetzen. Escape drücken und den Befehl stattdessen in der Eingabe tippen.',
    'tui.app.stop_all_armed' => 'Alle laufenden Agenten werden gestoppt — "s" erneut innerhalb von 3 s drücken zum Bestätigen.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'fehlt — Zeichenbreitenberechnung (mb_*) nicht möglich; PHP mit ext-mbstring neu installieren',
    'appLaunch.doctor.intl_missing' => 'fehlt — Grapheme/IntlChar-Breitenberechnung nicht möglich; PHP mit ext-intl neu installieren',
    'appLaunch.notice.policy_changed' => '⚠ config.json oder hooks.yaml seit letztem Start geändert. Neue Projekt-Hooks bleiben nur für diesen Start in Quarantäne — ~/.candy-code/config.json und hooks.yaml prüfen, dann werden sie übernommen',
    'appLaunch.notice.project_policy_changed' => '⚠ Die hooks.yaml eines vertrauenswürdigen Projekts enthält Einträge, die der letzte Start nie gesehen hat. Neue Projekt-Hooks bleiben nur für diesen Start in Quarantäne — .candy-code/hooks.yaml des Repositories prüfen, dann werden sie übernommen',
    'appLaunch.notice.bypass_mode' => '⚠ Berechtigungsmodus ist bypass-permissions: jeder Tool-Aufruf läuft ohne Rückfrage. Ändern mit /permissions (TUI), --permission-mode, oder anderen Berechtigungsmodus in ~/.candy-code/config.json setzen',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p startet im Berechtigungsmodus default: ein unbeaufsichtigter Lauf verweigert jeden Tool-Aufruf, der nachfragen würde. --permission-mode übergeben (bypass-permissions führt alles aus) für Skript-Läufe',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview ist für diesen Start standardmäßig aktiv: markierte Auto-Modus-Aufrufe werden vom Titelmodell geprüft, und jede Prüfung ist ein kostenpflichtiger Modellaufruf. autoReview auf false in ~/.candy-code/config.json setzen zum Abmelden',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} hat die Berechtigungen dieses Starts eingeschränkt: {count} deny/ask-Regel(n) zuerst geladen, {dropped} allow-Regel(n) verworfen — eine Projektdatei kann kein allow erteilen',
    'appLaunch.notice.restricted' => '⚠ --restricted: dieser Start läuft ohne Code-Ausführungstools — Bash, PtyRun, Task, Workflow, ShellStop und mcp_call fehlen in jedem Modell-Set; Dateitools bleiben unter ihrer Pfadbeschränkung und /permissions kann die entfernten Tools nicht wiederherstellen',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: vertrauenswürdige Projektwurzeln, Bundles und fremde Skills, Befehle und Agenten werden für diesen Start ignoriert — er verhält sich, als wäre nie etwas vertrauenswürdig gewesen',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'Kein Provider konfiguriert, daher läuft diese Sitzung auf dem eingebauten Offline-Echo-Backend — Antworten werden lokal zurückgegeben, kein Modell wird aufgerufen. `candy-code doctor` ausführen, um zu sehen, was ein Provider braucht, dann Ctrl+P drücken zum Modellwechsel, sobald einer konfiguriert ist.',
    'keys.chat.repaint' => 'Bildschirm löschen und Frame neu zeichnen',
    'keys.unbound' => 'nicht gebunden',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ Der `async` Claude Code Hook `{hook}` wurde mit {code} beendet. Ein `async` Hook bittet darum, einen Tool-Aufruf zu beobachten statt ihn zu steuern, daher kann er keinen blockieren und der Aufruf lief weiter. Was er sagte: {reason}',
    'hooks.notice.claude_dialect' => '⚠ Der Claude Code Hook `{hook}` wurde mit {code} beendet, was Claude Code als nicht-blockierende Beschwerde statt als Entscheidung liest, daher lief der Tool-Aufruf weiter. Was er sagte: {reason}',
    'hooks.notice.said_nothing' => '(nichts auf stderr)',
    'hooks.notice.system_message' => '⚠ Der Hook `{hook}` hat eine Nachricht für dich: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'Der HTTP-Hook `{hook}` ist mit einer URL konfiguriert, die nicht verwendet werden kann ({reason}); das angezeigte Ziel ist {target}. Ein Hook, der nicht angeben kann, wohin er geht, hat diesen Aufruf nicht genehmigt.',
    'hooks.http.deny_scheme' => 'Der HTTP-Hook `{hook}` nennt {target}, was keine http- oder https-URL ist. candy-code ruft Hooks nur über diese beiden Schemata an, und der Aufruf wird verweigert statt über einen Transport ausgeführt, den niemand geprüft hat.',
    'hooks.http.deny_credentials' => 'Der HTTP-Hook `{hook}` enthält Anmeldedaten in seiner URL ({target}). Ein Passwort in einer URL landet in Logs und Proxies, daher wird es hier verweigert; stattdessen als Header senden, dessen Wert einen `allowedEnvVars`-Namen liest.',
    'hooks.http.deny_blocked_target' => 'Der HTTP-Hook `{hook}` kann nicht befragt werden: {reason} ({target}). Private und Link-Local-Adressen werden nach derselben Regel verweigert wie ein ausgehender Abruf, und eine Wache, die nie erreicht wurde, hat diesen Aufruf nicht genehmigt.',
    'hooks.http.deny_unanswered' => 'Der HTTP-Hook `{hook}` hat nicht geantwortet ({reason}); das Ziel war {target}. Ein Hook, der nicht erreichbar war, hat diesen Aufruf nicht genehmigt, daher wird er verweigert.',
    'hooks.http.deny_header_injection' => 'Der HTTP-Hook `{hook}` kann seinen `{field}`-Header nicht senden: der Name oder sein Wert enthält ein Steuerzeichen, was Request-Framing statt Header-Wert ist. Nichts wurde an {target} gesendet und der Aufruf wird verweigert.',
    'hooks.http.notice_unanswered' => '⚠ Der HTTP-Hook `{hook}` hat nicht geantwortet ({reason}), daher konnte er den Aufruf nicht steuern. Er wurde an {target} gefragt.',
    'hooks.http.reason_unreachable' => 'die Verbindung oder die Anfrage lief innerhalb des eigenen Hook-Timeouts ab',
    'hooks.http.reason_oversized' => 'die Antwort war größer als {bytes} Bytes und endete nirgends',
    'hooks.http.reason_no_status' => 'die Antwort enthielt keine HTTP-Statuszeile',
    'hooks.http.reason_redirect' => 'es leitete weiter, und ein Hook-Aufruf folgt keinen Weiterleitungen',
    'hooks.http.reason_status' => 'die Antwort war kein 2xx-Status',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'Der Prompt-Hook `{hook}` hat nicht geantwortet ({reason}). Ein Hook, dessen Urteil nie zurückkam, hat diesen Aufruf nicht genehmigt, daher wird er verweigert.',
    'hooks.prompt.notice_unanswered' => '⚠ Der Prompt-Hook `{hook}` hat nicht geantwortet ({reason}), daher konnte er den Aufruf nicht steuern.',
    'hooks.prompt.reason_call_failed' => 'das Modell konnte nicht befragt werden',
    'hooks.prompt.reason_empty_verdict' => 'Der Prompt-Hook `{hook}` hat diesen Aufruf ohne Begründung verweigert.',
    'hooks.prompt.reason_no_backend' => 'dieser Start hat kein Titel-Backend, um es zu befragen',
    'hooks.prompt.reason_no_prompt' => 'der Eintrag enthält einen leeren Prompt zum Befragen',
    'hooks.prompt.reason_unparseable' => 'die Antwort war nicht das einzelne JSON-Objekt mit einem booleschen `ok`, das als Antwort verlangt wird',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Modell, das das `Advisor`-Tool für eine zweite Meinung konsultiert; nicht gesetzt — Standard — bietet das Tool gar nicht an (kein Billigmodell-Fallback: der Sinn ist ein Modell, das du gewählt hast).',
    'settings.allowedTools.help' => 'Whitelist von Tool-Namen oder Globs; nicht gesetzt bietet jedes Tool an.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: der Trailer und die PR-Zeile, die die Git-Anleitung verlangt.',
    'settings.autoCommit.help' => 'off, turn (ein Commit pro Runde, Nachricht vom Titelmodell) oder edit (einer pro Write/Edit); /undo macht es rückgängig.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'Unter auto wird ein Aufruf, den der Sicherheitsklassifikator markiert (außer einem Sicherheitsbefund, der immer nachfragt), vom Titelmodell geprüft, das ihn erlaubt, nachfragt oder verweigert. Standardmäßig aktiv, wenn ein prüfbares Modell existiert, und ein Start, der diesen Standard nutzt, sagt das einmal; false setzen zum Abmelden. Jede Prüfung ist ein kostenpflichtiger Modellaufruf.',
    'settings.autoReviewModel.help' => 'Das `provider/model`, auf dem der Auto-Reviewer läuft, z. B. `openai/gpt-4.1-mini`; leer bedeutet das Titelmodell. Ein Provider, der nicht aufgebaut werden kann, lässt den Reviewer aus mit einer Startwarnung.',
    'settings.autoReviewScope.help' => 'Was `autoReview` an den Reviewer sendet: `shell` (Standard) ist jeder nicht-Read-Only-Shell-Befehl, den die Musterliste durchließ; `writes` prüft auch `Edit`, `Write`, `ApplyPatch` und `WebFetch`, mit dem ausstehenden Diff für die Schreibtools; `all` prüft jeden Aufruf, den die Liste durchließ. Jede andere Schreibweise verhält sich wie `shell`. Jede Prüfung ist ein kostenpflichtiger Modellaufruf.',
    'settings.autoTest.help' => 'Nach einer Runde, die eine Datei bearbeitet hat, `testCommand` ausführen; bei Fehlschlag geht die Ausgabe zurück ans Modell, höchstens 3× pro Runde.',
    'settings.bashInteractiveIdleSeconds.help' => 'Sekunden, die ein `interactive: true` Bash-Lauf nichts ausgeben darf, bevor er als wartend auf Tastendruck gestoppt wird.',
    'settings.bashMaxTimeoutSeconds.help' => 'Der größte `timeout`, den ein Bash-Befehl verlangen darf; größere Werte werden darauf begrenzt.',
    'settings.bashSandbox.help' => 'Linux führt Bash in bubblewrap aus; macOS führt es in einem Seatbelt-Profil via `sandbox-exec` aus — beschreibbar nur im Arbeitsverzeichnis (`no-network` kappt auch das Netzwerk). `allowlist` (Linux) leitet Netzwerk-Egress über den Egress-Proxy des Starts, der nur die in `sandboxAllowedDomains` gelisteten Hosts gewährt: mit der Standard-LEEREN Liste verhält es sich GENAU wie `no-network`, bis du Hosts listest, und selbst dann scheitern Nicht-HTTP-Traffic (ssh, Datenbank-Ports) und jeder nicht gelistete Host. Auf macOS wird `allowlist` als `no-network` durchgesetzt. Verweigert Befehle, wenn die Jail nicht starten kann; ein unbekannter Wert bedeutet `no-network`, nie `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Auf `true` setzen, damit ein sandgeboxter `Bash`-Befehl seinen eigenen User-Namespace anlegen kann, was rootless podman oder buildah und eine Chromium-Sandbox brauchen. Das Standard-`false` führt bubblewrap mit `--unshare-user --disable-userns` aus, was den üblichen Weg zurück aus einer Mount-Jail blockiert; auf einem Host, dessen bubblewrap zu alt für diese Flags ist, läuft die Jail das einfache Set und ihre eigene Beschreibung sagt das.',
    'settings.bashTimeoutSeconds.help' => 'Sekunden, die ein Bash-Befehl laufen darf, wenn das Modell kein `timeout` übergibt; nie über der Bash-Obergrenze.',
    'settings.chatToolTimeoutSeconds.help' => 'Wall-Clock-Budget eines Batches von Tool-Aufrufen, den der Chat-native-Pfad (`command`-Provider) forkt; Nachzügler werden gekillt.',
    'settings.claudeMcpArgs.help' => 'Argumente für diese Binary; nicht gesetzt nutzt den Transport-Standard.',
    'settings.claudeMcpBinary.help' => 'Absoluter Pfad der `claude`-Binary, die der claude-mcp-Transport spawnen darf.',
    'settings.claudeMcpEnv.help' => 'Wörtliche Umgebungsvariablen, die an diese Binary übergeben werden.',
    'settings.compaction.autoPercent.help' => 'Fensteranteil, ab dem ältere Wechsel automatisch komprimiert werden, bevor der Prompt gesendet wird.',
    'settings.compaction.autoTokens.help' => 'Absolute Obergrenze für die automatische Stufe und das Runden-Schritte-Budget. 0 schaltet die Obergrenze aus.',
    'settings.compaction.blockPercent.help' => 'Fensteranteil, ab dem ein Prompt verweigert wird, bis Platz freigegeben wird; die einzige Stufe, die verweigert.',
    'settings.compaction.blockTokens.help' => 'Absolute Obergrenze für die blockierende Stufe; standardmäßig nicht gesetzt. Setzen lässt eine Obergrenze Prompts verweigern.',
    'settings.compaction.idleAuto.help' => 'Komprimiert eine inaktive Session über dem Tier-Schwellenwert während der Inaktivität, statt auf die nächste Eingabe zu warten, unter Verwendung der Mechanik des automatischen Tiers (Ausgabenlimit und Thrash-Schutz greifen). off: nie; hour: nach dem vollständigen compaction.idleOfferSeconds-Fenster; cacheTtl: kurz vor Ablauf des Prompt-Caches des Providers — eine Stunde, wenn der Provider Cache-Breakpoints setzt, ca. 5 Min. bei serverseitigen Caches, nie wenn nichts gecacht gemeldet wird — sobald der Verlauf unter eine Untergrenze des automatischen Tiers fällt, da die nächste Eingabe sonst die gesamte Konversation ungecacht vorladen würde; beim 60-Sekunden-Tick faltet ein 5-Min-Cache bei ca. 4 Min. Inaktivität. Erfordert einen Hintergrund-Provider-Aufruf; benötigt compaction.idleOfferSeconds > 0. Ein Bool wird weiterhin gelesen: true bedeutet hour, false bedeutet off.',
    'settings.compaction.idleOfferSeconds.help' => 'Eine Session, die ihr gesamtes Kontextfenster überschritten hat und so lange unberührt lag, bekommt /compact angeboten, statt die Eingabe zu senden. 0 bietet nie an.',
    'settings.compaction.keepRecent.help' => 'Anzahl der neuesten Nutzer-/Assistent-Austausche, die eine Kompaktierung vollständig behält.',
    'settings.compaction.mode.help' => 'llm: das Zusammenfassungsmodell schreibt die Zusammenfassungen (die Heuristik ist der Fallback); heuristic: lokale einzeilige Zusammenfassungen, niemals ein Modellaufruf; off: nichts komprimiert sich selbstständig, /compact funktioniert weiterhin und die Blockierungsstufe verweigert weiterhin.',
    'settings.compaction.modelTokenCaps.help' => '"<model>" oder "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} überschreibt die drei Obergrenzen; 0 setzt eine zurück.',
    'settings.compaction.refillLimit.help' => 'Anzahl aufeinanderfolgender automatischer Kompaktierungen, die direkt über ihr Tier zurückkommen dürfen, Eingabe ungesendet, bevor die nächste Eingabe verweigert statt erneut kompaktiert wird.',
    'settings.compaction.reminderPercent.help' => 'Fensteranteil, ab dem die „Kompaktierung erwägen"-Erinnerung und die vorausschauende Hintergrund-Zusammenfassung starten; unter dem automatischen Tier.',
    'settings.compaction.reminderTokens.help' => 'Absolutes Limit für das Erinnerungs-Tier: es feuert bei min(Prozentsatz, diesem Wert). 0 schaltet das Limit aus.',
    'settings.compaction.summaryAssistantChars.help' => 'Assistent-Antworten länger als dieser Wert werden in einer Heuristik-Summary-Zeile zu „[exchanged information]".',
    'settings.compaction.summaryUserChars.help' => 'Zeichen einer Nutzernachricht, die die Heuristik-Summary-Zeile behält.',
    'settings.compaction.toolOutputChars.help' => 'Zeichen der Assistent-Hälfte eines kondensierten Austauschs, die dem Zusammenfassungsmodell gezeigt werden.',
    'settings.connectTimeoutSeconds.help' => 'Limit für das Erreichen eines Provider-Hosts (DNS, TCP, TLS); kein Request-Timeout.',
    'settings.contextPruning.compress.help' => 'manual bietet Compress nur in einem Turn an, den du mit /compress startest, ein Aufruf; auto bietet es in jedem Turn an, in dem das Modell kürzen kann.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Tool-Ergebnisse seit der letzten Eingabe, nach denen eine lange Tool-Schleife zum Kürzen erinnert wird.',
    'settings.contextPruning.maxContextTokens.help' => 'Kontextgröße, ab der die neueste Zeile die stärkere „jetzt kürzen"-Erinnerung trägt.',
    'settings.contextPruning.minContextTokens.help' => 'Kontextgröße, unter der das Modell nie zum Kürzen erinnert wird; darf das Hard-Reminder-Limit nicht überschreiten.',
    'settings.contextPruning.mode.help' => 'auto entfernt ersetzte Zeilen bei jedem Turn-Start; manual nur bei /sweep; off zeigt keine Ref-Tags. /pruning überschreibt dies pro Sitzung.',
    'settings.contextPruning.nudgeFrequency.help' => 'Neue Zeilen, die eine Erinnerung nach der letzten abwartet, damit sie sich nicht bei jedem Schritt wiederholt.',
    'settings.contextWindow.help' => 'Token-Fenster-Überschreibung: eine Anzahl für das Modell des Providers oder {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Jede abgelehnte Custom-Command-Verzeichnis- oder Datei auf stderr ausgeben, nicht nur die einzeilige Zählung beim Start.',
    'settings.debug.rules.help' => 'Jede abgelehnte Rules-Verzeichnis- oder Datei auf stderr ausgeben.',
    'settings.debug.skills.help' => 'Jede übersprungene Skill-Datei und jedes abgelehnte Skills-Verzeichnis auf stderr ausgeben, nicht nur die einzeilige Zählung beim Start.',
    'settings.debug.stream.help' => 'Die Zeile „onToken observer threw, detaching it" auf stderr ausgeben, wenn ein Embedder-Streaming-Sink mitten im Zug fehlschlägt.',
    'settings.diffPreviewRows.help' => 'Zeilen eines Edit- oder Write-Diffs, die im Transcript gezeigt werden, bevor der Rest zusammengefasst wird.',
    'settings.diffStyle.help' => 'Diff-Layout im Transcript: `auto` malt Hunks nebeneinander auf breiten Terminals (120 Spalten oder mehr) und unified sonst, `unified` immer eine Spalte, `split` immer zwei. Diff-Bodies werden in beiden Layouts pro Token eingefärbt; die `+`/`-`-Markierungsspalte behält ihre Farbe.',
    'settings.disabledMcpServers.help' => '`.mcp.json`-Servernamen oder Globs (`untrusted_*`), die nie gestartet, aufgelistet oder aufgerufen werden, für den Haupt-Agenten und jeden Sub-Agenten.',
    'settings.disabledRules.help' => 'User-Tier-Regel-Packs, die ab dem ersten Zug nicht in den Prompt aufgenommen werden.',
    'settings.disabledSkills.help' => 'Skills aus der Discovery entfernt; hat auch Vorrang vor enabledSkills.',
    'settings.disabledTools.help' => 'Tool-Namen oder Globs, die aus dem modellseitigen Tool-Set entfernt werden.',
    'settings.doubleEscSeconds.help' => 'Wie schnell die zweite Esc auf die erste folgen muss, um einen laufenden Zug abzubrechen.',
    'settings.embeddingModel.help' => 'Embedding-Modell für den pro-Zug-Memory-Recall; nicht gesetzt rankt Notizen nur nach Schlüsselwort.',
    'settings.enabledSkills.help' => 'Skills, deren vollständige Bodies jeden Zug im System-Prompt mitführen.',
    'settings.env.diffMaxBytes.help' => 'Bytes, die jeder der beiden git-diff-Abschnitte behält, bevor er mit einer Notiz gekürzt wird.',
    'settings.env.gitDiffAfterWrites.help' => 'Nach einem Schritt, der Dateien geschrieben hat, die gestagten und ungestagten git-Diffs im Zugkontext anzeigen.',
    'settings.expandToolOutput.help' => 'Jede abgeschlossene Tool-Ausgabe vollständig im Transkript anzeigen; Ctrl+O oder ein Klick klappt sie weiterhin ein.',
    'settings.extraBody.help' => 'Top-Level-Request-Felder, die jedem `custom`-Provider-Request hinzugefügt werden.',
    'settings.formatCommands.help' => 'Formatierungsbefehl nach der Bearbeitung pro Dateiendung ({"php": "vendor/bin/php-cs-fixer fix {file}"}); wird vor dem Lint nach der Bearbeitung ausgeführt und schreibt die Datei neu. Standardmäßig deaktiviert.',
    'settings.formatAuto.help' => 'Die eingebaute Extension-Tabelle (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, das projekt-eigene node_modules prettier) darf eine bearbeitete Datei formatieren, wenn `formatCommands` keinen Befehl für ihre Extension nennt. Explizite Einträge gewinnen; ein Projekt braucht weiterhin `trustedProjectHooks`. Standardmäßig aus.',
    'settings.globMaxMatches.help' => 'Pfade, die ein Glob sammelt, bevor sein Walk stoppt; das Ausgabe-Limit begrenzt weiterhin das Ergebnis.',
    'settings.grepTimeoutSeconds.help' => 'Sekunden, die eine Grep-Suche laufen darf, bevor sie gekillt wird; bis zur Deadline gefundene Treffer kommen als Teilergebnis zurück.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Sekunden, die ein Hook-Eintrag ohne `timeout:` laufen darf, bevor er gekillt und als Ablehnung gezählt wird.',
    'settings.includeGitInstructions.help' => 'Ob die generische Commit-Anleitung des Bash-Tools im System-Prompt mitläuft.',
    'settings.instructions.help' => 'Globs von Dateien, deren Inhalte autoritativer System-Prompt-Text werden.',
    'settings.instructions.walkToRoot.help' => 'Opt-in: auch Anweisungsdateien oberhalb der nächsten .git-Markierung lesen, bis aber ohne das Home-Verzeichnis. Nur User-Tier; jeder Lesevorgang behält sein Containment- und Größenbudget.',
    'settings.instructionsExclude.help' => 'Globs von Anweisungsdateien, die übersprungen werden, als Ablehnungen protokolliert; nur User-Tier — ein Repository kann seinen Operator nicht stummschalten. Dateien innerhalb des Checkouts matchen per checkout-relativem Pfad; Ahnen- und erzwungene Dateien außerhalb matchen per absolutem Pfad, sodass `**/CLAUDE.local.md` auch die Ahnen-Kopien erreicht.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: ein ZUSÄTZLICHES Tastenkürzel an eine Bindungs-ID binden (die /keys-Referenz benennt sie) — Ctrl+<key>, Alt+<key>, Shift+<key> oder eine einzelne Funktionstaste; das mitgelieferte Tastenkürzel funktioniert weiterhin. Vorhanden-aber-unbrauchbar verweigert den Start; entferne die Taste für die mitgelieferten Bindungen.',
    'settings.layout.help' => 'Das Docked-Pane-Manifest; wird von der Shell geschrieben, wenn Panes sich bewegen.',
    'settings.lintCommands.help' => 'Lint-Befehl nach der Bearbeitung je Dateiendung ({"php": "…", "js": false}); `php -l` ist integriert.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: Server für Post-Edit-Diagnosen, Read-Gliederungen und das Lsp-Tool.',
    'settings.lspAutoDetect.help' => 'Den Language-Server starten, den ein Projekt-Fingerprint nennt (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml oder setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer), wenn seine Binary auf PATH liegt; manuelle `lsp`-Einträge gewinnen pro Sprache. Das Starten eines Servers führt dessen Code und den Build-Code im geöffneten Baum aus, daher starten Fingerprints Server nur in Projekten, die du für Hooks vertraut hast; ein unvertrauter Root startet keinen und protokolliert den Skip in den Start-Notizen.',
    'settings.maxCheckpoints.help' => 'Zug-Checkpoints, auf die /rewind zurückkehren kann, pro Session; die ältesten werden über diesem Wert gekürzt.',
    'settings.maxCostUsd.help' => 'Neue Züge verweigern, sobald der vom Provider gemeldete Ausgaben eines Starts diese Anzahl US-Dollar erreicht; nicht gesetzt bedeutet kein Limit. /budget ändert es nur für den laufenden Start.',
    'settings.maxOutputTokens.help' => 'Pro-Request-Ausgaben-Deckel; nicht gesetzt sendet keinen Override und der Provider-Standard greift.',
    'settings.maxToolSteps.help' => 'Provider-Aufrufe, die ein Zug machen darf; nicht gesetzt behält den Engine-Standard.',
    'settings.mcp.enabled.help' => 'Starte die MCP-Server, die in der .mcp.json eines vertrauenswürdigen Projekts aufgeführt sind; off startet keine, und die Oberflächen melden den Start als deaktiviert.',
    'settings.mcp.lazySchemaTokens.help' => 'Schema-Tokens, die ein MCP-Server advertise darf, bevor seine Tools an mcp_list/mcp_call delegieren; 0 delegiert nie.',
    'settings.mcpResultCapBytes.help' => 'Maximale Bytes, die eine MCP-Tool-Antwort dem Modell übergeben darf.',
    'settings.memory.autoConsolidate.help' => 'Dauerhafte Fakten aus abgeschlossenen Zügen ins Memory speichern und das Kompaktierungs-Journal hinein falten (der Dream-Pass); jeder ist ein abgerechneter Aufruf.',
    'settings.memory.dreamIntervalSeconds.help' => 'Mindestzeit zwischen zwei Dream-Pässen für ein Projekt; jeder Pass ist ein abgerechneter, schreibgeschützter Zug.',
    'settings.memory.dreamProposeSkills.help' => 'Den Dream-Pass Skills als Entwürfe in ~/.candy-code/skills-proposed vorschlagen lassen; keine ist aktiv, bis du sie mit /skills akzeptierst.',
    'settings.memory.entryMaxBytes.help' => 'Längste Index-Zeile einer Notiz, bevor sie gekürzt angezeigt wird; wird auf das User-Notiz-Budget gesenkt, wenn darüber.',
    'settings.memory.projectNoteMaxBytes.help' => 'Größte einzelne Projekt-Memory-Notiz, wenn sie in das .candy-code/memory/ des Repositorys geschrieben wird.',
    'settings.memory.promptMaxBytes.help' => 'Byte-Budget für die Notiz-Zeilen des Memory-Index; das User-Notiz-Budget wird gesenkt, um hinein zu passen.',
    'settings.memory.promptMaxEntries.help' => 'Maximale Notizen, die der Prompt-Memory-Index auflistet, neueste zuerst; User-Notizen zählen darin mit.',
    'settings.memory.userMaxBytes.help' => 'Byte-Budget für die User-Scope-Zeilen, innerhalb des Gesamtbudgets.',
    'settings.memory.userMaxEntries.help' => 'Maximale Anzahl deiner projektübergreifenden (User-Scope-)Notizen, die zuerst gelistet werden, innerhalb der Notizanzahl.',
    'settings.modelPrices.help' => 'USD pro 1 Mio. Tokens pro Modell ({"input": …, "output": …}), für die Gesamtausgaben und Obergrenze.',
    'settings.models.help' => 'Das auszuführende Modell je Anbieter ({"<provider>": "<model id>"}); ohne Angabe wird der Anbieterstandard verwendet.',
    'settings.mouse.help' => 'Mausereignisse an candy-code melden (Klicks, Mausrad, Auswahl); off gibt dem Terminal seine eigene copy-on-select-Funktion zurück.',
    'settings.mouseClicks.help' => 'Klicken und Ziehen wirken auf das, was sie treffen; off behält das Mausrad und ignoriert Klicks.',
    'settings.notices.transcriptLimit.help' => 'Maximale Start-Warnungen, die als Transcript-Zeilen gesetzt werden; der Rest wird in einer „and N more"-Zeile gezählt, und stderr trägt sie alle.',
    'settings.notify.help' => 'off, bell (BEL) oder osc9 (eine Desktop-Benachrichtigung): wird gesendet, wenn ein Turn endet und wenn der Agent auf eine Freigabe wartet.',
    'settings.paletteMru.help' => 'Wie viele kürzlich verwendete Palette-Zeilen gemerkt und zuerst gerankt werden; 0 merkt keine.',
    'settings.parallelToolCalls.help' => 'Die schreibgeschützten Tool-Aufrufe eines Zugs parallel ausführen.',
    'settings.parallelToolDeadlineSeconds.help' => 'Wall-Clock-Deckel für einen Batch parallel dispatchter Tool-Aufrufe.',
    'settings.permissionMode.help' => 'Wie Tool-Aufrufe gegatet werden. Wird nie aus einer Projektdatei übernommen.',
    'settings.permissionRules.help' => 'Geordnete allow / deny / ask-Regeln, die bei jedem Tool-Aufruf geprüft werden. Die gemeinsame settings.json eines vertrauenswürdigen Projekts kann deny / ask-Einträge hinzufügen — nur einschränkend.',
    'settings.permissions.autoAllowReadOnly.help' => 'Unter default und accept-edits eine Bash-Zeile ausführen, die nur aus schreibgeschützten Befehlen besteht (ls, cat, grep, git log, …; keine Datei-Umleitung, keine Substitution, cd nur innerhalb des Projekts), ohne Rückfrage. Ein Projekt kann dies nur deaktivieren.',
    'settings.permissions.autoStrikeLimit.help' => 'Unter auto machen so viele aufeinanderfolgende blockierte Aufrufe einer Kategorie den nächsten zu einer Frage.',
    'settings.permissions.autoTotalLimit.help' => 'Unter auto: Nach dieser Anzahl blockierter Aufrufe in einer Sitzung wird bei jedem weiteren Block nachgefragt.',
    'settings.pluginPaths.help' => 'Zusätzliche Verzeichnisse, die nach Claude-format Plugin-Bundles durchsucht werden, neben den zwei installierten Roots; ein Wert kann ein Bundle selbst oder ein Container von Bundles benennen. Nur User-Tier — ein Checkout kann keine eigenen Plugins einschreiben.',
    'settings.promptCache.keepWarm.help' => 'Erlaubte Warm-Pings pro Leerlaufphase; 0 (Standard) deaktiviert. Jeder Ping sendet den eingefrorenen Präfix einer Leerlauf-Sitzung erneut, zusammen mit einer Anweisungszeile, die eine Ein-Zeichen-Antwort verlangt, damit der Anbieter seinen Prompt-Cache auffrischt, bevor die TTL abläuft und der nächste Prompt die gesamte Konversation nicht ungecacht vorfüllt. Er feuert nur dort, wo der cacheTtl-Fold abgelehnt wurde – unter seiner Untergrenze oder vor seiner Stunde –, auf demselben Tick/Alarm, auf dem der Fold-Watch bereits läuft, niemals mitten im Turn, niemals mehr als einer gleichzeitig, niemals über diese Anzahl pro Phase hinaus. Dies sind kostenpflichtige Aufrufe einer Sitzung, die niemand beobachtet; das Ausgabenlimit greift weiterhin. Die Anzahl erscheint in /usage unter `warm`.',
    'settings.promptCache.help' => 'Ob die `vertex`- und `bedrock`-Provider Prompt-Cache-Breakpoints setzen.',
    'settings.promptSuggestionHistory.help' => 'Neueste Nachrichten (jede auf 2000 Zeichen gekürzt), die dem Prompt-Suggestion-Aufruf gezeigt werden.',
    'settings.promptSuggestions.help' => 'Nach jedem Zug das Titel-Modell nach der Nachricht fragen, die du wahrscheinlich als Nächstes senden wirst, und sie ausgegraut im leeren Eingabefeld anzeigen (→ akzeptiert sie).',
    'settings.provider.help' => 'Welcher LLM-Provider die Session anspricht; jede Eingabe wird an dessen Host gesendet.',
    'settings.providerRetryAttempts.help' => 'Aufrufe pro Provider-Request bei transientem Fehler (Netzwerk, 5xx, 408, 429), der erste inklusive; 1 wiederholt nie.',
    'settings.providerRetryBaseBackoffMs.help' => 'Wartezeit vor dem ersten Retry eines fehlgeschlagenen Provider-Aufrufs; jede weitere Wartezeit verdoppelt sich.',
    'settings.providers.help' => 'Provider-Definitionen pro Name ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); jeder Eintrag überlagert die Standardwerte dieses Typs. Nur Benutzerebene: Ein Projekt darf niemals ändern, wohin deine Zugangsdaten gesendet werden.',
    'settings.queueMode.help' => 'steer (der Agent liest es beim nächsten Schritt), followup (nach dem Durchlauf gesendet) oder interrupt (Durchlauf beim nächsten Schritt stoppen, dann senden). Tab reiht immer ein.',
    'settings.readMaxBytes.help' => 'Obergrenze für einen Read-Aufruf; die folgende Seite zeigt die übliche Größe eines Leseergebnisses.',
    'settings.readPageBytes.help' => 'Bytes, die eine Read-Seite fassen kann, Zeilennummern inklusive, unabhängig davon, was `limit` verlangt.',
    'settings.readPageLines.help' => 'Zeilen, die ein Read zurückgibt, wenn der Aufruf kein `limit` nennt.',
    'settings.reasoningEffort.help' => 'Thinking-Stufe, gesendet, wo das Paar sie formt: openai (o-Serie und gpt-5, nicht die -chat-Builds), anthropic und vertex (claude-3-7 und neuer; vertex antwortet auf beiden claude- und gemini-Zweigen), gemini (2.5 und neuer), sglang (bei jeder Anfrage weitergeleitet), bedrock (claude-IDs, als Thinking-Budget), codex und claude-code (benannte Stufen an die CLI weitergeleitet); nicht gesetzt oder unbekannt verlangt nichts. `/effort` setzt und löscht sie.',
    'settings.redactToolOutput.help' => 'Standardmäßig aus: Abgeschlossene Tool-Ausgaben werden exakt so in den Verlauf und sessions.db gespeichert, wie sie zurückkamen. Wenn aktiviert, wird jedes Tool-Ergebnis durch denselben Redaktor geschleust, der auch den Speicher und `/share` schützt, sobald es abgeschlossen ist — erkannte Zugangsdaten werden in den gespeicherten Bytes und in dem, was spätere Runden dem Modell zurückspielen, zu `[REDACTED]` (das Tool selbst führt unverändert aus). Bild-, Dokument- und Nutzungsfelder bleiben unberührt. `/export` fügt keine eigene Redaktion hinzu: Es druckt exakt das Gespeicherte, daher bleibt alles, was vor dem Aktivieren gespeichert wurde, roh.',
    'settings.references.help' => 'Eine Liste von `[{"path": "…", "name": "…"}]`-Verzeichnissen außerhalb des Workspace, die Read, Grep, Glob und Ls ebenfalls öffnen dürfen, schreibgeschützt; jedes wird im `<env>`-Block mit einer begrenzten Karte dessen, was dort liegt, angezeigt. Die Workspace-Jail bleibt für Write, Edit und Bash unverändert — eine Referenz erweitert nie, was geschrieben werden kann. Nur Benutzerstufe: Ein ausgechecktes Repository kann kein Lese-Wurzelverzeichnis hinzufügen. Ein fehlender oder Nicht-Verzeichnis-Pfad oder einer innerhalb des Session-Wurzelverzeichnisses wird beim Start mit einer Meldung abgelehnt.',
    'settings.repoMap.enabled.help' => 'Die Karte, wo Code liegt (Pakete und PSR-4-Quellverzeichnisse), in den System-Prompt einfügen.',
    'settings.repoMap.maxBytes.help' => 'Byte-Budget für jeden der beiden Abschnitte der Repo-Karte; Einträge darüber hinaus werden gezählt, nicht aufgelistet.',
    'settings.requireReadBeforeWrite.help' => '`Edit`, ein `Write`, das eine bestehende Datei überschreibt, und ein `ApplyPatch`-Abschnitt, der eine Datei ändert, verschiebt oder löscht, verweigern, bis das Modell diese Datei in dieser Sitzung gelesen hat; das Anlegen neuer Dateien wird nie blockiert. Standardmäßig aus: Dateien, die das Modell gelesen hat, bleiben in beiden Fällen durch die geänderte-auf-der-Platte-Regel geschützt.',
    'settings.resumeCostWarnUsd.help' => 'Nach einer veralteten Wiederaufnahme wird die erste Eingabe einmal gehalten, wenn das erneute Senden des Verlaufs auf mindestens so viele Dollar ohne Cache geschätzt wird; Enter erneut drücken, um trotzdem zu senden, oder zuerst /compact. 0 deaktiviert das Halten.',
    'settings.sandboxAllowedDomains.help' => 'Die Hosts, die die `allowlist`-Jail erreichen darf: einfache Namen (`example.com`), `*.example.com`-Wildcards und `host:port`-Schreibweisen (Standard: nichts). Wird nur verwendet, wenn `bashSandbox` auf Linux `allowlist` ist; mit einer LEEREN Liste verhält sich `allowlist` GENAU wie `no-network`. Der Egress-Proxy gewährt HTTP(S) und nichts anderes — jeder nicht gelistete Host wird mit 403 beantwortet, und Nicht-HTTP-Traffic (ssh, Datenbank-Ports) schlägt fehl. Ein fehlerhafter Eintrag wird bei der Durchsetzung IGNORIERT: Ein Tippfehler kann die Gewährung nur verkleinern, nie erweitern. Nur Benutzerstufe: Ein ausgechecktes Repository darf kein Loch in die Jail schlagen, in der es ankam. macOS erzwingt `allowlist` als `no-network` — der Loopback-Port-Zweig ist ein nachverfolgtes Folgethema.',
    'settings.sandboxScope.help' => 'Welche Befehle außerhalb des Tool-Pfads der `bashSandbox`-Jail beitreten: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (Standard: keine). Aktiv nur solange `bashSandbox` nicht `off` ist — die Liste sagt, wer die Jail teilt, nie ob eine existiert. Ein nicht erkannter Eintrag liest sich als JEDER Bereich (strengster, wie ein nicht erkannter `bashSandbox`-Wert), und das Einstellungs-Audit nennt ihn. Eine Jail, die nicht starten kann, verweigert die Arbeit, statt sie frei laufen zu lassen: Skript-Hooks verweigern, lint, format und test überspringen mit Grund, und ein eingesperrter LSP- oder MCP-stdio-Server wird nicht gestartet. `lsp`-Einträge und Benutzerstufen-MCP-Einträge tragen ein pro-Server-`"sandbox": false`-Opt-out; Projektstufen-MCP-Opt-outs werden ignoriert.',
    'settings.screenReader.help' => 'Darstellung für Screenreader-Nutzer. Ein: Die App legt Dekoration ab, die ein Reader nicht vorlesen kann — der Agent-Spinner haftet auf einem statischen Rahmen, und Box-Zeichen-Rahmen, Reverse-Video-Menüauswahl und dergleichen weichen Klartext und einem hörbaren Signal, sobald jede Oberfläche den Schalter beachtet. Aus ist das bemalte Terminal wie üblich. Deine eigene Barrierefreiheits-Einstellung, wie der vim-Modus im Eingabefeld: Ein ausgechecktes Projekt kann sie nicht ändern. Wirkt beim nächsten Lesen nach dem Speichern — live, kein Neuladen.',
    'settings.rules.standingMaxBytes.help' => 'Byte-Budget, gerahmt und maskiert, für die Regel-Dateien, die ganz in jeden Prompt eingefügt werden; eine Regel darüber hinaus wird stattdessen durch eine Zeigerzeile benannt.',
    'settings.scrollWheelLines.help' => 'Transkriptzeilen, die ein Mausrad-Tick scrollt.',
    'settings.sd.apiKey.help' => 'Bearer-Schlüssel, gesendet an den Stable-Diffusion-Server, falls er einen verlangt; die `${VAR}`-Platzhalterform einem Literal vorziehen.',
    'settings.sd.baseUrl.help' => 'HTTP-Basis-URL einer AUTOMATIC1111-kompatiblen Stable-Diffusion-Webui (`http://127.0.0.1:7860`); Prompts, Bilder und der API-Schlüssel gehen alle dorthin raus.',
    'settings.sd.defaultModel.help' => 'Modell-ID, mit der Generierungsanfragen beginnen; der Server behält die Wahl für sich, wenn nicht gesetzt.',
    'settings.sd.presets.help' => 'Benannte Parameterbündel, die das Medienformular anbietet; die Form ist die der Medien-Pipeline selbst, für die Einstellungsebene opak.',
    'settings.sd.savePattern.help' => 'Dateinamen-Vorlage für gespeicherte Medien; die `[date]`-, `[time]`-, `[seed]`- und `[number]`-Token füllen sich beim Speichern.',
    'settings.sd.timeoutSeconds.help' => 'Sekunden, die eine Generierungsanfrage laufen darf, bevor sie aufgegeben wird; Diffusion auf einer schwachen GPU dauert routinemäßig Minuten.',
    'settings.secretEnvAllowlist.help' => 'Zugangsdaten-förmige Variablennamen (oder Globs), die Bash, Grep und Skript-Hooks weiterhin erben.',
    'settings.server.allowBypass.help' => 'Ob Server-Sitzungen in bypass-permissions oder dont-ask laufen dürfen (wie --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Hostnamen (oder host:port), auf die der Server neben den Loopback-Namen und seinen eigenen Adressen antwortet, z. B. die eines Reverse-Proxys.',
    'settings.server.allowedIps.help' => 'Client-IPs oder CIDR-Bereiche, die sich neben Loopback verbinden dürfen; alle anderen werden vor dem Login mit 403 abgelehnt. Leer: kein Adressfilter.',
    'settings.server.allowedOrigins.help' => 'Zusätzliche Browser-Origin (http(s)://host[:port]), die der Server neben seinen eigenen akzeptiert.',
    'settings.server.askTimeoutSeconds.help' => 'Sekunden, die eine Berechtigungsanfrage auf einen Client wartet, bevor sie abgelehnt wird; 0 wartet ewig.',
    'settings.server.browseRoot.help' => 'Das Verzeichnis, auf das server.dirBrowse beschränkt ist (wie --browse-root); nicht gesetzt ist dein Home-Verzeichnis.',
    'settings.server.dirBrowse.help' => 'Angemeldeten Clients erlauben, Verzeichnisnamen unter server.browseRoot aufzulisten und dort Sitzungen zu starten (wie --allow-dir-browse). Standardmäßig aus.',
    'settings.server.clientTools.help' => 'Clients mit Write-Bereich erlauben, Tools über tools.client.register zu registrieren, damit das Modell Code aufrufen kann, der im Client selbst läuft (client__*-Tools). Standardmäßig aus.',
    'settings.server.drainSeconds.help' => 'Sekunden, die ein stoppender Server auf laufende Runden wartet, bevor er sie abbricht; 0 stoppt sofort.',
    'settings.server.host.help' => 'Die Adresse, an die `serve` bindet. Alles außer Loopback braucht zusätzlich --allow-remote beim Start.',
    'settings.server.maxConcurrentTurns.help' => 'Runden, die ein Server gleichzeitig über seine Sitzungen hinweg fährt; eine weitere wird als busy abgelehnt (wiederholbar).',
    'settings.server.maxOpenSessions.help' => 'Sitzungen, die ein Server gleichzeitig offen hält; darüber hinaus wird die am längsten ungenutzte inaktive freigegeben.',
    'settings.server.port.help' => 'Der Port, an den `serve` bindet; 0 wählt einen freien.',
    'settings.server.trustedProxies.help' => 'IPs oder CIDRs, deren X-Forwarded-For / X-Forwarded-Proto der Server glaubt.',
    'settings.serviceTier.help' => 'Premium-Lane, gesendet, wo das Paar sie formt: openai verlangt `service_tier: "priority"` auf beiden Chat- und Responses-Zweigen, anthropic verlangt `speed: "fast"` (nur die claude-opus-5-5-GA-Familie und die claude-opus-5 / claude-opus-4-8-Research-Preview-Familien, deren erforderlicher Beta-Header automatisch mitläuft); nicht gesetzt oder unbekannt verlangt nichts. Der Fast-Modus berechnet eine Prämie, die keine modellbezogene Preistabelle ableiten kann: Während ein gestuftes Paar aktiv ist, landen seine Runden als unpreislich im Ledger, nie als geschätzter Tarif. Wirkt beim Start und bei jedem Provider- oder Modell-Neuaufbau.',
    'settings.sessionRetentionDays.help' => 'Jeder Start löscht unbenannte, nicht angeheftete Sitzungen, die so viele Tage unberührt waren, und nennt welche; 0 (Standard) behält alles.',
    'settings.sessions.autoTitle.help' => 'Benenne jede neue Sitzung anhand ihrer ersten Eingabe mit einem Aufruf des Titelmodells; Aus lässt sie unbenannt bis /rename.',
    'settings.sessions.awayRecap.help' => 'Wenn das Terminal nach einer Abwesenheit von drei Minuten oder mehr den Fokus zurückmeldet, wird eine Zusammenfassung ausgegeben, wo die Sitzung aufgehört hat (ein Aufruf des Titelmodells pro Abwesenheit); off lässt die Rückkehr stumm. `/recap` fragt jederzeit eine ab.',
    'settings.skills.listingMaxBytes.help' => 'Byte-Budget für die gesamte Skill-Auflistung im System-Prompt; Skills darüber hinaus werden zu einer Zeile "N weitere Skills" zusammengefasst.',
    'settings.skills.pathNudges.help' => 'Wenn ein Tool auf eine Datei zugreift, die von einer pfadbezogenen Skill abgedeckt wird, das Modell daran erinnern, dass diese Skill existiert, einmal pro Skill.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: ein Shell-Befehl, dessen Ausgabe die Statusleiste zeichnet, alle refreshSeconds (2 bis 3600, Standard 2) erneut ausgeführt. Er erhält die Sitzung als ein JSON-Dokument auf stdin (session_id, cwd, model, workspace, version, cost, plus candy_code-Erweiterungen); ein Befehl, der stdin nie liest, wird dennoch ausgeführt.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Sekunden, die ein verbundener Streaming-Server zum Senden seiner Antwortheader benötigen darf; niemals ein Gesamt-Timeout der Anfrage.',
    'settings.streamIdleTimeoutSeconds.help' => 'Sekunden, die ein Lesevorgang einer Streaming-Antwort auf Bytes warten darf, bevor die Verbindung als tot gilt; pro Lesevorgang, nie kumulativ.',
    'settings.subagentMaxActive.help' => 'Anzahl delegierter Läufe, die eine Sitzung gleichzeitig haben darf, jede Ebene, jedes Mitglied und jeder Hintergrund-Agent mitgezählt; darüber hinaus wird ein `Task`-Aufruf abgelehnt. Nicht gesetzt — Standard — oder 0 bedeutet kein Limit.',
    'settings.subagentMaxConcurrent.help' => '`Task`-Aufrufe einer Batch, die gleichzeitig laufen (der Rest wartet auf einen freien Slot), und die Breite jedes Agent-Pools. Nicht gesetzt — Standard — oder 0 setzt keine Obergrenze.',
    'settings.subagentMaxDepth.help' => 'Ebenen unterhalb der Sitzung, auf die ein delegierter Lauf sein darf; ein Lauf auf der letzten Ebene erhält kein `Task`. 1 erlaubt Sub-Agenten keine weitere Delegation.',
    'settings.subagentMaxTurns.help' => 'Schrittobergrenze für einen Sub-Agenten — eine `Task`-Delegation, eine Workflow-Phase oder ein `executeAgents`-Lauf — dessen Preset kein `maxTurns` deklariert.',
    'settings.subagentModel.help' => 'Modell, auf dem ein delegierter Sub-Agent läuft, wenn sein Preset auf `inherit` steht; nicht gesetzt folgt dem Modell der Sitzung.',
    'settings.summaryModel.help' => 'Modell für Komprimierungszusammenfassungen; ohne Angabe wird das eigene Modell der Konversation verwendet, das den Prompt-Cache wiederverwendet.',
    'settings.symbolMap.enabled.help' => 'Die gerankte symbolbasierte Repo-Map in den System-Prompt aufnehmen, einmal pro Sitzung erfasst.',
    'settings.temperature.help' => 'Sampling-Temperatur, die der `custom`-Anbieter sendet, wenn eine Anfrage keine angibt.',
    'settings.terminalBackground.help' => 'Was das adaptive Theme hinter dem Text annimmt: auto fragt das Terminal ab (OSC 11, dann COLORFGBG); light oder dark gibt es direkt an.',
    'settings.testCommand.help' => 'Shell-Befehl, der die Tests des Projekts im Projektstamm ausführt (`composer test`, `pytest -q`); was `autoTest` ausführt.',
    'settings.theme.help' => 'Farbthema; /theme und die Palette ändern es live. Benutzerdefinierte Themen werden aus JSON-Dateien unter ~/.candy-code/themes geladen.',
    'settings.thinkingBudget.help' => 'Thinking-Token-Budget: Gemini `thinkingConfig` beim `vertex`-Provider; erweitertes Denken beim `anthropic`-Provider, wobei die Untergrenze der Messages-API 1024 beträgt (0 oder nicht gesetzt bedeutet deaktiviert bei beiden Anbietern). Thinking-Tokens werden als Ausgabe abgerechnet.',
    'settings.titleModel.help' => 'Modell, das Sitzungen benennt und Prompt-Vorschläge erstellt; nicht gesetzt verwendet den günstigen Hilfsstandard des Provider-Typs vor dem Block-Modell.',
    'settings.transcriptJsonl.help' => 'Jedes übertragene Transkript in ein nur anhängbares JSONL-Journal unter `~/.candy-code/transcripts/<project>/` spiegeln (Dateien 0600) und Hook-Skripten einen `transcript_path`-stdin-Schlüssel übergeben, der darauf zeigt. Das Journal enthält die Rohkonversation und wächst unbegrenzt; wird beim Start gelesen, sodass Änderungen erst beim nächsten Start greifen.',
    'settings.toolInstructionCapBytes.help' => 'Maximale Byteanzahl, die ein Edit-, Write- oder ApplyPatch-Ergebnis des maßgeblichen CLAUDE.md/AGENTS.md-Inhalts tragen darf; der Rest wird mit einer Markierung gekürzt.',
    'settings.toolOutputCapBytes.help' => 'Maximale Anzahl Bytes, die ein Bash-, Grep-, Glob-, Lsp- oder WebFetch-Ergebnis an das Modell übergeben darf; abgeschnittener Inhalt wird in einer vom Ergebnis benannten Datei gespeichert.',
    'settings.toolOutputPreviewLines.help' => 'Zeilen eines eingeklappten Tool-Ergebnisses im Transkript; Strg+O klappt den Rest auf.',
    'settings.toolSpillCaptureBytes.help' => 'Der Großteil der Ausgabe eines Bash-Befehls (pro Stream) wird im Speicher gehalten und in die Spill-Datei gespeichert, wenn das Ergebnis gekürzt wird; niemals unter dem Ausgabe-Limit.',
    'settings.toolSpillMinCapBytes.help' => 'Kleinstes Ergebnislimit, ab dem ein gekürztes Tool-Ergebnis in eine Datei gespeichert wird; darunter wird die Kürzung nur angekündigt und der Rest verworfen.',
    'settings.toolSpillWindowPercent.help' => 'Maximaler Anteil des Kontextfensters, den ein Tool-Ergebnis belegen darf; bei Überschreitung wird das Ergebnis in eine Datei gespeichert und dem Modell nur Anfang und Ende angezeigt.',
    'settings.trustedProjectCommands.help' => 'Projektwurzeln, deren Slash-Befehle !`cmd`-Shell-Blöcke ausführen dürfen.',
    'settings.trustedProjectHooks.help' => 'Projektwurzeln, deren .candy-code/hooks.yaml ausgeführt werden darf.',
    'settings.trustedProjectMcp.help' => 'Projektwurzeln, deren .mcp.json-Server gestartet werden können.',
    'settings.trustedProjectSettings.help' => 'Projektwurzeln, deren .candy-code/settings*.json die Schlüssel der Projektstufe festlegen können.',
    'settings.turnIdleTimeoutSeconds.help' => 'Sekunden, die ein laufender Turn ohne Fortschritt verstreichen darf, bevor er als blockiert gestoppt wird; Leerlaufzeit, nie Gesamtzeit.',
    'settings.ui.imageRenderMode.help' => 'Wie generierte Bilder im Terminal dargestellt werden; `auto` wählt das beste vom Terminal gemeldete Protokoll.',
    'settings.ui.mediaDisplayOverrides.help' => 'Darstellungs-Feineinstellungen pro Render-Modus (Größenbegrenzungen, Fallbacks); Schlüssel sind die Render-Modus-Bezeichnungen, Werte die Darstellungsregler.',
    'settings.vimMode.help' => 'NORMAL/INSERT-Bearbeitung im Entwurfsfeld (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, Textobjekte di" da( ciw, Zähler 3dd d2w): Bewegungen, Ändern, Löschen und Kopieren in NORMAL, wörtliche Eingabe in INSERT. Ein Modus, keine Tastenbelegung — erscheint nie in /keys. Wirkt beim nächsten Tastendruck nach dem Speichern.',
    'settings.voice.apiKey.help' => 'Bearer-Schlüssel, der an den Transkriptions-Endpunkt gesendet wird, falls dieser einen erfordert; bevorzuge die `${VAR}`-Platzhalterform gegenüber einem Literal.',
    'settings.voice.baseUrl.help' => 'HTTP-Basis-URL eines OpenAI-kompatiblen Transkriptions-Endpunkts (ein abschließendes `/v1` wird beibehalten); die Aufnahme geht ausschließlich dorthin und nirgendwohin sonst. Kein Standardwert: Die Spracheingabe bleibt AUS, bis dies in der Benutzerebene festgelegt wird.',
    'settings.voice.language.help' => 'BCP-47-Code (`en`, `de`) erzwingt die Transkriptionssprache; ohne Wert erkennt der Endpoint die Sprache.',
    'settings.voice.maxSeconds.help' => 'Feste Sekunden-Obergrenze pro Aufnahme (5-600, Standard 120). Die Obergrenze ist an das Recorder-Argument gekoppelt, damit eine verwaiste Aufnahme sich selbst stoppt.',
    'settings.voice.model.help' => 'Modell-ID für jede Transkriptionsanfrage; `whisper-1` antwortet auf OpenAI-kompatiblen Endpunkten.',
    'settings.watchFiles.help' => 'Sende eine Eingabeaufforderung, wenn eine gespeicherte Datei einen Kommentar enthält, der mit AI! (Änderung vornehmen) oder AI? (Frage beantworten) endet; einfache AI-Kommentare werden als Kontext mitgegeben. Abfrage im Chat-Leerlauf; nur Kommentare, die nach dem Start gespeichert wurden, werden ausgelöst, jeweils einmal. Nur Terminal-Sitzungen: Der Watcher läuft im Terminalprozess, daher überwacht eine Sitzung, die von `candy-code serve` gehostet wird, keine Dateien.',
    'settings.webFetchMaxBytes.help' => 'Der Großteil eines abgerufenen Textkörpers wird im Speicher gehalten; eine Speicherbegrenzung – das Ausgabelimit bestimmt, was das Modell erreicht.',
    'settings.webFetchTimeoutSeconds.help' => 'Sekunden, die ein WebFetch-Socket-Read blockieren darf, bevor der Abruf fehlschlägt.',
    'settings.webSearchBackend.help' => 'Welcher Suchdienst für WebSearch-Abfragen: `searxng` (Standard) sendet jede Abfrage an den konfigurierten `webSearchEndpoint`; `brave`, `tavily` und `exa` verbinden sich stattdessen mit dem festen Host des jeweiligen Dienstes und benötigen ihren API-Schlüssel in der Umgebung (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), ohne dass sie auf eine andere URL umgeleitet werden können.',
    'settings.webSearchEndpoint.help' => 'Such-URL einer SearXNG-Instanz, der Sie vertrauen (`https://searx.example.org/search`); jede WebSearch-Abfrage wird dorthin gesendet.',
    'settings.webSearchMaxResults.help' => 'Ergebnisse einer WebSearch-Digestliste, jeweils mit Titel, URL und Auszug.',
    'settings.webSearchTimeoutSeconds.help' => 'Sekunden, die eine Suchanfrage dauern kann.',
    'settings.webhooks.help' => 'Zuordnung von Hook-Name zu {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} fügt den Body (als nicht vertrauenswürdig escaped) in den Prompt ein und startet eine Hintergrund-Session. Leer (Standard) mountet nichts. rate ist N Auslieferungen pro Minute pro Adresse und pro Hook insgesamt. bypass-permissions wird für Hooks beim Start abgelehnt; ein Hook ohne Modus läuft im strengeren von Server-Modus und Standard. Eine Zeile kann auch signature benennen: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: die Route verifiziert dann einen HMAC-SHA256 des Roh-Bodys (sha256=<hex>) mit dem Zeilen-Secret über den Signature-Header, anstelle des Custom-Header-Secrets, da GitHub keine Custom-Header senden kann; fehlgeschlagene Signaturen lösen denselben Per-Hook-Lockout aus, und eine bereits gesehene Delivery-ID (X-GitHub-Delivery standardmäßig für das GitHub-Schema; der konfigurierte deliveryHeader für ein generisches) antwortet {"ok": true, "duplicate": true}, ohne eine zweite Session zu starten.',
    'settings.webhooksOut.help' => 'Zuordnung von Endpunktname zu {url, secret, events}; events ist eine nicht-leere Liste aus turn.completed, session.ended, permission.asked und schedule.fired. Leer (Standard) öffnet keinen Egress. Nur aus dem USER-Tier gelesen — eine Projekt- oder Bundle-Konfiguration kann nie einen ausgehenden Endpunkt hinzufügen. url muss https sein, oder http nur wenn der wörtliche Host localhost oder eine Loopback-Adresse ist, und darf nie userinfo enthalten; secret ist mindestens 16 Zeichen lang und signiert jede Zustellung per HMAC-SHA256 als X-Candy-Code-Signature (sha256=<hex> über den exakten Body) gepaart mit X-Candy-Code-Timestamp. Zustellung erfolgt asynchron auf dem Event-Loop — Dispatches warten nie auf eine Antwort: eine 2-Sekunden-Connect-Grenze und ein 10-Sekunden-Netzwerk-Limit pro POST begrenzen jede Zustellung (Webhook-Grenzen, kein LLM-Request-Timeout), fehlgeschlagene Transports und 5xx-Antworten durchlaufen eine 2/8/30-Sekunden-Wiederholungsleiter, 4xx- und Redirect-Antworten sind beim ersten Mal endgültig, da Redirects abgelehnt statt gefolgt werden, und eine begrenzte Warteschlange von 128 laufenden Zustellungen verwirft neue Dispatches bei Überlauf, statt den Speicher zu vergrößern. Beim Start gelesen; Änderungen an der Zuordnung werden erst nach Neustart wirksam.',
    'settings.webhooksOut.refuse' => 'webhooksOut in der Benutzerkonfiguration ist unbrauchbar: {reason}. Start verweigert, statt an einen halbgeprüften Endpunkt zu liefern — Zuordnung korrigieren oder Schlüssel entfernen, um ohne ausgehende Webhooks zu laufen.',
    // --- end settings help ---

